private val EVENTS_TEXTE: Map<String, Map<String, String>> by lazy {
    mapOf(
        "de" to etexteDE(),
        "gsw" to etexteGSW(),
        "de-AT" to etexteDEAT(),
        "en" to etexteEN(),
        "fr" to etexteFR(),
        "it" to etexteIT(),
        "es" to etexteES(),
        "fi" to etexteFI(),
        "nl" to etexteNL(),
        "cs" to etexteCS(),
        "pl" to etextePL(),
        "pt" to etextePT(),
        "pt-PT" to etextePTPT(),
        "ja" to etexteJA(),
        "zh" to etexteZH(),
        "ru" to etexteRU(),
        "id" to etexteID(),
        "nb" to etexteNB(),
    )
}

internal fun eventsText(key: String, lang: String): String? {
    if (key !in EVENTS_SCHLUESSEL) return null
    return EVENTS_TEXTE[lang]?.get(key) ?: EVENTS_BRUECKE[lang]?.let { EVENTS_TEXTE[it]?.get(key) } ?: EVENTS_TEXTE["en"]?.get(key)
}

