private fun etexteDEAT(): Map<String, String> = mapOf(
    "imp.ai1" to "Analyse einzelner Sessions (Fehlersuche, Plausibilitätsprüfung)",
    "imp.ai2" to "Verbesserung unserer Erkennungsmodelle (Pump- und On-Foil-Erkennung)",
    "imp.ai3" to "Weiterentwicklung der App",
    "imp.ai4" to "Recherche fehlender Foils und Stabilizer für den Katalog",
    "imp.aiIntro" to "Für Auswertung und Weiterentwicklung setzen wir den KI-Assistenten Claude von Anthropic ein. Dabei können Session- und Rohdaten, Feedback sowie Chat-Nachrichten — auch Direktnachrichten — an Anthropic übertragen und dort verarbeitet werden, zu diesen Zwecken:",
    "imp.aiNote" to "Anthropic verarbeitet die Inhalte in unserem Auftrag; nach den geltenden API-Bedingungen werden sie nicht zum Training der Sprachmodelle genutzt. Die Verarbeitung kann in den USA erfolgen. Der Assistent kann im Chat unter eigenem Namen antworten (Konto „Claude Code AI“). Näheres in der <a href=\"https://www.anthropic.com/legal/privacy\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-brand-400 hover:underline\">Datenschutzerklärung von Anthropic</a>.",
    "imp.aiTitle" to "KI-Unterstützung (Anthropic Claude)",
    "imp.apple1" to "<b>Zugriff:</b> deine E-Mail-Adresse (ggf. die von Apple anonymisierte „Hide-My-Email“-Relay-Adresse), deinen Namen (nur einmalig bei der Erst-Anmeldung, falls von dir freigegeben) und die Apple-Nutzer-ID.",
    "imp.apple2" to "<b>Verwendung:</b> ausschließlich zum Erstellen und Anmelden deines Pumpfoil-Kontos.",
    "imp.apple3" to "Keine Weitergabe an Dritte, keine Werbung, kein KI-/ML-Training. Für die Apple-seitige Verarbeitung ist Apple nach deren Datenschutzrichtlinie verantwortlich.",
    "imp.appleIntro" to "Wenn du dich mit Apple anmeldest, verarbeiten wir ausschließlich die folgenden Daten:",
    "imp.appleTitle" to "Apple-Anmeldung („Mit Apple anmelden“)",
    "imp.community1" to "<b>Anzeigename</b> und <b>Profilbild</b> (wenn gesetzt; ohne Anzeigename erscheint die Session ohne Namen).",
    "imp.community2" to "<b>Alle Sessions mit erkanntem Foiling</b>: Datum/Uhrzeit, <b>Spot</b> (Gewässername aus OpenStreetMap), die <b>Karte/GPS-Strecke</b> (also <u>wo</u> gefoilt wurde), Anzahl Läufe, Distanz, Geschwindigkeit, Puls, Pump-/Gleitwerte und die hochgeladenen <b>Fotos</b>.",
    "imp.community3" to "<b>Rekorde &amp; Bestenlisten</b> (Name, Wert, Spot, Anzahl Sessions/Läufe/Spots).",
    "imp.community4" to "<b>Likes</b> (Anzahl) und die <b>Anzahl</b> der „wirkt unecht“/„unangemessen“-Stimmen.",
    "imp.community5" to "<b>Online-Status</b>: ein grüner Punkt am Profilbild, solange du die App oder die Seite offen hast. Gespeichert wird nur der Zeitpunkt deiner letzten Aktivität (auf die Minute). Im Profil abschaltbar.",
    "imp.community6" to "<b>Kommentare</b> unter Sessions mit Anzeigename, Profilbild und Zeitpunkt. Der Inhaber einer Session kann Kommentare im Profil ausschalten und fremde Kommentare unter seiner Session löschen; eigene Kommentare kannst du eine Stunde lang bearbeiten oder löschen. Mit deinem Konto werden sie vollständig gelöscht.",
    "imp.community7" to "<b>Teams</b>: deine Mitgliedschaften mit Rolle (wer die Mitgliederliste sieht, legt die Teamleitung fest), deine Plätze in Team-Bestenlisten und Event-Abzeichen auf deiner Profilseite. Einzelheiten unter „Teams“.",
    "imp.community8" to "<b>Chats</b>: Spot-Chats lesen alle Angemeldeten, mit Anzeigename und Profilbild. Den Team-Chat lesen nur aktive Mitglieder des Teams, Direktnachrichten nur die beiden Beteiligten. Blockieren kannst du jeden.",
    "imp.communityIntro" to "Ein Konto kann jeder anlegen. Eingeloggt sieht man von <b>allen</b> Nutzern:",
    "imp.communityNote" to "Sessions sind <b>nicht anonym</b> — sie sind der Person über ihren Anzeigenamen zugeordnet. Du kannst jede Session jederzeit einzeln löschen; nur von dir <b>ausgeblendete</b> Sessions scheinen nicht in den Community-Listen auf (auch reine GPS-Sessions werden angezeigt).",
    "imp.communityTitle" to "👥 Für jede registrierte Person sichtbar (Community)",
    "imp.conn1" to "Beim Verknüpfen wirst du zum jeweiligen Anbieter weitergeleitet und meldest dich dort an (OAuth). Wir erhalten ein Zugriffs-Token sowie die von dir freigegebenen Trainings-/Workout-Daten (u. a. GPS-Strecke, Zeit, Herzfrequenz).",
    "imp.conn2" to "Diese Daten werden ausschließlich als deine eigenen Sessions importiert und wie deine übrigen Sessions behandelt.",
    "imp.conn3" to "Die Verknüpfung ist jederzeit unter „Verknüpfte Konten“ widerrufbar — dabei wird das gespeicherte Token gelöscht.",
    "imp.connIntro" to "Optional und nur auf deine ausdrückliche Aktion hin kannst du ein Konto eines Drittanbieters verknüpfen, um Aktivitäten zu importieren:",
    "imp.connTitle" to "Verknüpfte Konten (Polar, COROS, Suunto)",
    "imp.fb1" to "<b>Zugriff:</b> deine E-Mail-Adresse, deinen Vornamen und deine Facebook-Nutzer-ID. Nachnamen und Profilbild holen wir uns nicht.",
    "imp.fb2" to "<b>Verwendung:</b> ausschließlich zum Anlegen und Anmelden von deinem Pumpfoil-Konto und um deinen Vornamen in der App herzuzeigen.",
    "imp.fb3" to "Es gibt <b>keinen Zugriff</b> auf weitere Facebook-Daten — keine Freundesliste, keine Beiträge, keine Fotos, keine Seiten.",
    "imp.fb4" to "Diese Daten werden <b>nicht an Dritte weitergegeben</b>, nicht für Werbung verwendet und nicht zum Trainieren von KI-/ML-Modellen genutzt.",
    "imp.fb5" to "Auf dieser Website rennt <b>kein Facebook-Skript und kein Pixel</b>. Die Anmeldung ist eine Weiterleitung, die erst losgeht, wenn du den Knopf drückst — vorher hat Facebook mit deinem Besuch nichts zu tun.",
    "imp.fbIntro" to "Wenn du dich mit deinem Facebook-Konto anmeldest, verarbeiten wir ausschließlich die folgenden Daten:",
    "imp.fbNote" to "Entfernst du pumpfoil.org in deinen Facebook-Einstellungen, löschen wir die Verknüpfung automatisch; dein Pumpfoil-Konto bleibt. Den Stand von so einer Anfrage findest du unter <a href=\"/datenloeschung\" class=\"text-brand-400 hover:underline\">Datenlöschung</a>, und dein Konto ganz löschen kannst du jederzeit selber im Profil.",
    "imp.fbTitle" to "Facebook-Anmeldung („Weiter mit Facebook“)",
    "imp.friends1" to "Freunde sehen deine ganze Profilseite, auch Abschnitte, die du im Profil ausgeblendet hast, und dein Gewicht.",
    "imp.friends2" to "Wenn du gerade pumpst, sehen sie, an welchem Spot, und bekommen eine Nachricht, auch wenn du dich auf der Spot-Karte ausgeblendet hast. In Session-Liste und Bestenlisten gibt es eine Ansicht nur mit Freunden.",
    "imp.friends3" to "Verborgene Orte bleiben verborgen, deine Rohdaten bleiben privat. Du siehst dasselbe von ihnen. Beendet einer von euch die Freundschaft, sieht ab sofort keiner mehr die Freundes-Angaben des anderen.",
    "imp.friendsTitle" to "🤝 Deine Freunde (erst wenn beide zugestimmt haben)",
    "imp.garmin1" to "<b>Welche Daten:</b> nur Aktivitäten, die du nach dem Verknüpfen aufzeichnest – Strecke, Zeit, Geschwindigkeit, Herzfrequenz und, falls die Uhr sie aufgezeichnet hat, die Beschleunigung. Aktivitäten ohne GPS verwerfen wir, außer sie gehören zu einer Aufnahme unserer eigenen Uhr-App. Welche Profile ankommen, wählst du unter „Uhr & Konten“. Ältere Aktivitäten und Gesundheitsdaten (Schlaf, Stress, Schritte …) rufen wir nicht ab.",
    "imp.garmin2" to "<b>Wozu:</b> um deine Fahrten zu erkennen und dir anzuzeigen, mit persönlichen Rekorden, Spots und den Bestenlisten der Community. Dort sind sie wie deine übrigen Sessions für angemeldete Nutzer sichtbar.",
    "imp.garmin2b" to "In öffentlichen Team-Bestenlisten und globalen Events erscheinen Platz, Anzeigename und Wert auch ohne Anmeldung (siehe „Öffentlich“ oben).",
    "imp.garmin3" to "<b>Wer sie bekommt:</b> niemand außer uns. Gespeichert wird auf unserem Server bei der Hetzner Online GmbH (Auftragsverarbeitung, siehe oben). Wir verkaufen Garmin-Daten nicht und geben sie nicht an Dritte weiter.",
    "imp.garmin4" to "<b>Keine KI:</b> Garmin-Daten werden nicht automatisch an KI-Dienste übertragen und nicht zum Trainieren oder Bewerten von KI-Modellen genutzt. Die Auswertung läuft auf unserem Server mit eigenem Code. Nur wenn du uns ausdrücklich um Hilfe zu einer bestimmten Session bittest, kann diese eine Session im Rahmen der KI-Unterstützung (siehe unten) angesehen werden.",
    "imp.garmin5" to "<b>Deine Rechte:</b> Du kannst deine Sessions jederzeit ansehen, als Datei herunterladen, einzeln löschen oder mit „Konto löschn“ alles entfernen. Die Verknüpfung trennst du unter „Uhr & Konten“ oder in Garmin Connect; dabei löschen wir das gespeicherte Zugriffs-Token.",
    "imp.garminIntro" to "Wenn du dein Garmin-Connect-Konto verknüpfst (freiwillig, unter „Uhr & Konten“), gilt zusätzlich:",
    "imp.garminTitle" to "Garmin Connect",
    "imp.gh1" to "Im Repository liegen auch Screenshots der Apps. Sie können zeigen, was eingeloggte Mitglieder in der App sehen, zum Beispiel Anzeigenamen von Fahrern in Rekorden oder als Autoren von Uhr-Layouts sowie Spot-Namen.",
    "imp.gh2" to "Wenn du deinen Namen dort nicht sehen willst, schreib uns, dann machen wir ihn in den aktuellen Dateien unkenntlich. Ältere Fassungen bleiben in der Versionsgeschichte des Repositorys erhalten, solange diese nicht umgeschrieben wird.",
    "imp.gh3" to "pumpfoil.org verlinkt GitHub nur und lädt nichts von dort. Wenn du github.com öffnest, gilt die Datenschutzerklärung von GitHub.",
    "imp.gh4" to "Pumpfoil wird mit Hilfe des KI-Assistenten Claude entwickelt, der Änderungen am Quelltext selbstständig auf GitHub veröffentlicht. Nutzerdaten gehören dort nicht hin und werden nie absichtlich hochgeladen; jede Veröffentlichung wird automatisch darauf geprüft. Trotzdem lässt sich nicht ausschließen, dass versehentlich Ausschnitte öffentlich werden, zum Beispiel Anzeigenamen, Orte und Zeiten von Sessions oder Sensordaten (GPS-Strecken, Bewegungsdaten, Puls). Was einmal auf GitHub stand, kann von anderen kopiert worden sein und lässt sich dann nicht mehr vollständig zurückholen. <b>Wer dieses Risiko nicht eingehen möchte, sollte mit Pumpfoil keine Sessions aufzeichnen oder hochladen.</b>",
    "imp.ghIntro" to "Pumpfoil ist Open Source. Quelltext, Dokumentation und Changelog liegen öffentlich auf GitHub (github.com/kechel/pumpfoil, ein Dienst der GitHub, Inc.):",
    "imp.ghTitle" to "Quelltext auf GitHub",
    "imp.google1" to "<b>Zugriff (Data Accessed):</b> deine E-Mail-Adresse, dein Vorname und deine Google-Konto-ID (sub).",
    "imp.google2" to "<b>Verwendung (Data Usage):</b> ausschließlich zum Erstellen und Anmelden deines Pumpfoil-Kontos sowie zur Anzeige deines Vornamens in der App.",
    "imp.google3" to "Es erfolgt <b>kein Zugriff</b> auf weitere Google-Dienste oder -Daten (kein Google Drive, Gmail, Kalender o. Ä.).",
    "imp.google4" to "Diese Daten werden <b>nicht an Dritte weitergegeben</b>, nicht für Werbung verwendet und nicht zum Training von KI-/ML-Modellen genutzt.",
    "imp.googleIntro" to "Wenn du dich mit deinem Google-Konto anmeldest (Google Sign-In / OAuth), verarbeiten wir ausschließlich die folgenden Google-Nutzerdaten:",
    "imp.googleNote" to "Die Verwendung von Informationen aus Google-APIs entspricht der <a href=\"https://developers.google.com/terms/api-services-user-data-policy\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-brand-400 hover:underline\">Google API Services User Data Policy</a>, einschließlich der Limited-Use-Anforderungen.",
    "imp.googleTitle" to "Google-Anmeldung (Google-Nutzerdaten)",
    "imp.host1" to "Die <b><a href=\"https://smartkomm.de/\" target=\"_blank\" rel=\"noopener noreferrer\">SmartKomm GmbH</a></b> stellt den Server (eine virtuelle Maschine) <b>gratis</b> zur Verfügung; ihr Geschäftsführer betreibt dieses Projekt privat. Verantwortlich für pumpfoil.org und alle Daten ist allein der Betreiber laut Impressum.",
    "imp.host2" to "Der Server steht bei der <b><a href=\"https://www.hetzner.com\" target=\"_blank\" rel=\"noopener noreferrer\">Hetzner Online GmbH</a></b>. Mit Hetzner besteht ein <b>Vertrag zur Auftragsverarbeitung (AVV) nach Art. 28 DSGVO</b>.",
    "imp.hostTitle" to "Server und Hosting",
    "imp.huawei1" to "<b>Übertragung:</b> Die Uhren-App schickt deine Aufnahme (GPS-Strecke, Zeit, Bewegungsdaten, Herzfrequenz) über HUAWEI Health an die Pumpfoil-App auf deinem Android-Handy (HUAWEI Wear Engine), die sie zu pumpfoil.org hochlädt. HUAWEI WATCH 3, 4 und 5 können stattdessen direkt hochladen, nachdem du sie per Code verknüpft hast.",
    "imp.huawei2" to "<b>Zugriff auf dem Handy:</b> nur Grunddaten deiner gekoppelten HUAWEI-Uhren (Name, Verbindungsstatus, ob die Pumpfoil-Uhren-App installiert ist). Wir lesen keine Daten aus deiner HUAWEI ID, aus HUAWEI Health oder aus anderen Apps.",
    "imp.huawei3" to "Die Aufnahmen werden ausschließlich als deine eigenen Sessions gespeichert und wie deine übrigen Sessions behandelt. Keine Weitergabe an Dritte, keine Werbung.",
    "imp.huawei4" to "Du kannst den Zugriff jederzeit widerrufen: in der Pumpfoil-App auf der Karte „HUAWEI-Uhr“ („Trennen“) oder in HUAWEI Health. Für die Verarbeitung auf Huawei-Seite ist Huawei nach seiner eigenen Datenschutzrichtlinie verantwortlich.",
    "imp.huaweiIntro" to "Wenn du mit der Pumpfoil-App auf einer HUAWEI-Uhr aufnimmst, kommt die Aufnahme über dein Handy zu uns:",
    "imp.huaweiTitle" to "HUAWEI-Uhren (HUAWEI Health / Wear Engine)",
    "imp.intro" to "Diese App ist eine Community: Foil-Sessions werden mit anderen geteilt. Hier steht genau, welche Daten für wen sichtbar sind.",
    "imp.map1" to "Die <b>Straßenkarte</b> stammt von <b>OpenStreetMap</b>. Beim Anzeigen einer Karte lädt dein Browser die Kartenausschnitte direkt von deren Servern; dabei werden deine IP-Adresse und der angezeigte Ausschnitt übertragen. Anbieter: OpenStreetMap Foundation, Vereinigtes Königreich.",
    "imp.map2" to "Schaltest du oben rechts auf <b>Satellit</b>, kommen die Luftbilder von <b>Esri</b> (Esri, Maxar, Earthstar Geographics) — ebenfalls direkt von deren Servern und ebenfalls mit deiner IP-Adresse. Das passiert <b>nur</b>, wenn du umschaltest; deine Wahl wird lokal in deinem Browser gemerkt.",
    "imp.mapApple" to "In der <b>iPhone- und Apple-Watch-App</b> kommen Karte UND Luftbild von <b>Apple Maps</b>, nicht von OpenStreetMap oder Esri. Beim Anzeigen einer Karte überträgt dein Gerät den angezeigten Ausschnitt an Apple; verantwortlich dafür ist Apple nach deren Datenschutzrichtlinie. In der <b>Android-App</b> gilt dasselbe wie im Browser: Straßenkarte von OpenStreetMap, Luftbild von Esri.",
    "imp.mapSpots" to "<b>Spot-Namen</b> sucht unser Server zu den Koordinaten eines Spots bei OpenStreetMap-Diensten (Nominatim und Overpass, darunter der Overpass-Spiegel von VK/mail.ru). Übertragen werden nur die Koordinaten des Spots, keine Kontodaten. Liegt ein Spot auf dem Meer, nehmen wir den nächsten Ort aus <b>GeoNames</b> (geonames.org, CC BY 4.0), einer Liste, die bei uns auf dem Server liegt.",
    "imp.mapTitle" to "Karten",
    "imp.mcp1" to "Optional kannst du einem KI-Programm (z. B. Claude von Anthropic) Lesezugriff auf deine eigenen Aufnahmen geben, nur wenn du es auf unserer Zustimmungsseite ausdrücklich erlaubst (OAuth).",
    "imp.mcp2" to "Das Programm darf nur lesen, und nur deine eigenen Aufnahmen, Summen und Bestwerte samt Ausrüstung. Keine Daten anderer Fahrer, keine Fotos, Videos, Nachrichten oder Bewertungen, keine aussortierten oder gelöschten Aufnahmen.",
    "imp.mcp3" to "Was das Programm abruft, verarbeitet dessen Anbieter nach seinen eigenen Bedingungen. Beenden kannst du den Zugriff jederzeit unter „Verknüpfte Konten“.",
    "imp.mcpTitle" to "KI-Programme mit deinen eigenen Aufnahmen (KI-Zugang)",
    "imp.operator1" to "E-Mail-Adressen, alle Rohdaten, Geräte-Verknüpfungen und technische Server-Logs.",
    "imp.operator2" to "Passwörter werden nur als gesalzener Hash (PBKDF2) gespeichert — auch ich sehe sie nicht im Klartext.",
    "imp.operator3" to "Technisch kann der Betreiber alle gespeicherten Inhalte einsehen, auch Direktnachrichten und Team-Chats (siehe auch „KI-Unterstützung“).",
    "imp.operatorTitle" to "🛠 Nur der Betreiber (Jan)",
    "imp.owner1" to "<b>Rohdaten</b> deiner Sessions (einzelne GPS-Punkte, 25-Hz-Beschleunigung) — z. B. fürs Labeln.",
    "imp.owner2" to "Labels, Trimmen, Neu-Analysieren, Fotos hochladen/löschen.",
    "imp.owner3" to "Deine <b>E-Mail-Adresse</b> und Konto-Einstellungen — nie für andere Nutzer sichtbar.",
    "imp.owner4" to "Wer deine Session geliked hat, siehst nur du; andere sehen nur die Anzahl. Wer „wirkt unecht“ oder „unangemessen“ gemeldet hat, wird niemandem angezeigt.",
    "imp.owner5" to "<b>Laufende Aufnahmen</b>: Lädt dein Handy-Recorder live hoch (Schalter „Live hochladen“ im Profil, abschaltbar), gehen GPS- und Bewegungsdaten schon während der Aufnahme an unseren Server. Dass und seit wann aufgenommen wird, siehst du auf deinen anderen Geräten und deinen Uhren. Mit Namen sehen das außer dir nur deine bestätigten Freunde, samt Spot (siehe „Deine Freunde“); ohne Namen kann dein Spot auf der Spot-Karte grün werden (nächster Punkt). Bei Uhren leiten wir „nimmt vermutlich auf“ allein aus dem Zeitpunkt ab, zu dem sich die Uhr-App zuletzt gemeldet hat. Die Session selbst erscheint anderen erst, wenn sie abgeschlossen ist.",
    "imp.owner6" to "<b>Aktive Spots</b>: Die Spot-Karte färbt Spots grün, an denen vermutlich gerade jemand pumpt. Wir nehmen dafür den Spot im Umkreis von 1 km um deine laufende Handy-Aufnahme oder um die Position, die deine Uhr beim Start einmal meldet (gespeichert wird nur der Spot, nicht die Position), nach dem Hochladen den Spot deiner Session. Ist kein Spot in der Nähe, hat die Session keine erkannten Läufe oder löschst du sie, zählst du nicht als aktiv. Ein einzelner Spot wird nur grün, wenn dort in den letzten 180 Tagen mindestens 4 Fahrer waren; kleinere Spots färben nur ein Bündel, und nur, wenn die Spots dieser Gegend in den letzten 90 Tagen mehr als 5 Fahrer hatten. Namen werden nicht gezeigt. Abschalten kannst du das im Profil („Auf der Spot-Karte zeigen“).",
    "imp.ownerTitle" to "🔒 Nur du selbst (Besitzer der Session)",
    "imp.privacyText" to "Alle hochgeladenen Daten werden dauerhaft gespeichert. Zum Löschen nutze bitte den Button „Konto löschen“ in deinem Profil (Web-App oder iOS-/Android-App) — er entfernt dein Konto mit allen Sessions, Rohdaten und Fotos endgültig. Die Übertragung läuft verschlüsselt (HTTPS).",
    "imp.privacyTitle" to "Datenlöschung",
    "imp.public1" to "<b>Hochgeladene Fotos</b> und <b>Profilbilder</b>: Die Bilddateien liegen unter einem zufälligen, nicht erratbaren Link. Wer diesen Link kennt (z. B. weitergeleitet), kann das Bild auch ohne Konto öffnen. EXIF-/GPS-Daten in Fotos werden beim Upload entfernt.",
    "imp.public2" to "Die Web-App selbst und der Download der Uhr-App.",
    "imp.public3" to "<b>Öffentliche Team-Bestenlisten</b>: Schaltet die Leitung eines Teams dessen Bestenlisten öffentlich, sieht sie jeder ohne Anmeldung, auch über geteilte Event-Links: Platz, Anzeigename, Initialen und Wert. Sessions, Spots und Profilbilder sehen nur Angemeldete. Suchmaschinen nehmen Teamseiten nicht auf.",
    "imp.public4" to "<b>Globale Events</b> von pumpfoil.org: Daran nimmt automatisch teil, wer passende Sessions hat, ohne sich anzumelden. Ihre Bestenlisten sind über den Event-Link auch ohne Login sichtbar (Platz, Anzeigename, Initialen, Wert), und deine Werte zählen für die Team-Wertung deiner Teams. Abschalten kannst du das im Profil unter „Privatsphäre“ mit „Nicht an globalen Events teilnehmen“; dann fehlst du auch in schon beendeten Events.",
    "imp.publicTitle" to "🌍 Öffentlich (jeder im Internet, ohne Login)",
    "imp.teams1" to "<b>Du entscheidest</b>, ob du einem Team beitrittst; der Beitritts-Dialog sagt dir vorher, ob seine Bestenlisten gerade öffentlich sind. Austreten kannst du jederzeit, dann verschwindest du sofort aus den Bestenlisten des Teams. Nur in schon beendeten Events bleibst du im eingefrorenen Ergebnis.",
    "imp.teams2" to "<b>Die Teamleitung entscheidet</b>, ob die Bestenlisten öffentlich sind, wer die Mitgliederliste sieht (nur Mitglieder oder alle Angemeldeten) und welche Bestenlisten und Events es gibt. Mit dem Beitritt stimmst du zu, dass die Bestenlisten öffentlich sein können, auch wenn sie es gerade nicht sind; dann sind dein Anzeigename und dein Platz ohne Anmeldung sichtbar. Einzelne Mitglieder lassen sich nicht ausblenden.",
    "imp.teams3" to "Es zählen alle deine Sessions, auch die von vor dem Beitritt, bei Events nur die im Zeitfenster. Platz 1 bis 3 eines Events bekommen ein Abzeichen auf ihrer Profilseite.",
    "imp.teams4" to "Bei einer Beitrittsanfrage sehen Leitung und Moderatoren, an welchen Spots und in welchen Sportarten du bisher unterwegs warst (nur die Zahl der Sessions).",
    "imp.teams5" to "Nach außen erscheint ein Team mit Name, Beschreibung, Wappen und Bild erst nach unserer Freigabe. Wird dein Konto gelöscht, verschwindest du aus allen Teams und Bestenlisten, auch aus eingefrorenen Event-Ergebnissen.",
    "imp.teamsTitle" to "🏁 Teams: was du entscheidest und was die Teamleitung festlegt",
    "imp.title" to "Impressum",
    "imp.werteText" to "Wir sagen genau eines zu: Auf dem Server läuft der öffentliche Quellcode von GitHub. Angezeigt wird, was er aus den hochgeladenen Daten berechnet, auch wenn das falsche oder unerwartete Zahlen sind. Dass Messwerte, Sessions, Rekorde, Bestenlisten und Events korrekt sind oder ned manipuliert wurden, sagen wir ned zu.",
    "imp.werteTitle" to "Messwerte und Anzeigen",
    "imp.whoSees" to "Datenschutz",
    "imp.yt1" to "Auf der Startseite zeigen wir Vorschaubilder unseres YouTube-Kanals. Diese werden über <b>unseren eigenen Server</b> ausgeliefert — beim Laden der Seite entsteht <b>kein</b> Kontakt zu Google und es werden <b>keine</b> Cookies gesetzt.",
    "imp.yt2" to "Erst wenn du ein Video <b>anklickst</b>, wird der YouTube-Player im Modus „erweiterter Datenschutz“ (youtube-nocookie.com) geladen — das gilt für die Startseite und für den Community-Feed. Dann erhält Google/YouTube deine IP-Adresse und kann Cookies setzen. Mit dem Klick willigst du darin ein.",
    "imp.ytNote" to "Anbieter: Google Ireland Ltd. Näheres in der <a href=\"https://policies.google.com/privacy\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-brand-400 hover:underline\">Datenschutzerklärung von Google</a>.",
    "imp.ytTitle" to "Eingebettete YouTube-Videos",
    "ref.ablehnen" to "Ablehnen",
    "ref.alsEntwurf" to "Als Entwurf speichern",
    "ref.anlegen" to "Korrektur vorbereiten",
    "ref.aufheben" to "Aufheben",
    "ref.aufhebenFrage" to "Korrektur aufheben? {lauf} von {fahrer} zählt dann wieder, und der Fahrer wird benachrichtigt.",
    "ref.bearbeiten" to "Bearbeiten",
    "ref.bearbeitetAm" to "bearbeitet am {am}",
    "ref.bestaetigen" to "Damit wird {lauf} von {fahrer} aus der Wertung genommen, Grund und öffentlicher Kommentar erscheinen auf der Eventseite, und der Fahrer wird benachrichtigt.",
    "ref.bestaetigtVon" to "veröffentlicht von {von}",
    "ref.diskussion" to "Diskussion (nur Referees)",
    "ref.einleitung" to "Läufe in kontrollierten Schritten aus der Wertung nehmen: Eine Korrektur beginnt als Entwurf, geht zur Prüfung und wirkt erst, wenn sie veröffentlicht ist. Veröffentlichte Korrekturen stehen auf der Eventseite, und der Fahrer wird benachrichtigt.",
    "ref.entwurfHinweis" to "Wird als Entwurf gespeichert: ohne Wirkung und nur für Referees sichtbar.",
    "ref.erstellt" to "Angelegt von {von} · {am}",
    "ref.fehler.eigener_lauf" to "Den eigenen Lauf kannst du nicht melden.",
    "ref.fehler.frist_abgelaufen" to "Der Endstand steht fest, das wirkt nicht mehr.",
    "ref.fehler.grund" to "Bitte einen Grund wählen.",
    "ref.fehler.kein_lauf" to "Dieser Lauf wurde in der Session nicht gefunden.",
    "ref.fehler.kein_referee" to "Das dürfen nur Referees.",
    "ref.fehler.melden_vorbei" to "Meldungen sind nur bis zum Festschreiben möglich.",
    "ref.fehler.nicht_in_wertung" to "Melden können nur Fahrer, die in der Wertung stehen.",
    "ref.fehler.nicht_mehr_aenderbar" to "Veröffentlichte oder erledigte Korrekturen sind nicht mehr änderbar.",
    "ref.fehler.schon_gemeldet" to "Dieser Lauf wurde schon gemeldet.",
    "ref.fehler.schon_vorhanden" to "Für diesen Lauf gibt es schon eine Korrektur.",
    "ref.fehler.uebergang" to "Dieser Schritt ist aus dem aktuellen Status nicht möglich.",
    "ref.fehler.zu_viele" to "Zu viele Meldungen für dieses Event.",
    "ref.feldGrund" to "Grund",
    "ref.feldIntern" to "Interne Notiz (nur Referees)",
    "ref.feldOeffentlich" to "Öffentlicher Kommentar (steht auf der Eventseite)",
    "ref.frist" to "Korrekturen können bis {zeit} wirken.",
    "ref.fristAbgelaufen" to "Der Endstand steht fest; Korrekturen wirken nicht mehr.",
    "ref.fristOffen" to "Das Event ist noch offen; Korrekturen wirken, sobald sie veröffentlicht sind.",
    "ref.grund.andere_sportart" to "Andere Sportart",
    "ref.grund.ausserhalb_fenster" to "Außerhalb des Eventfensters",
    "ref.grund.doppelte_aufnahme" to "Dieselbe Fahrt doppelt aufgezeichnet",
    "ref.grund.fremdkraft" to "Fremdkraft (Welle, Boot, Zug)",
    "ref.grund.messfehler" to "Messfehler (GPS-/Tempo-Sprung)",
    "ref.grund.sonstiges" to "Sonstiges",
    "ref.grundFest" to "Der Grund steht nach dem Veröffentlichen fest; zum Ändern die Korrektur aufheben und neu anlegen.",
    "ref.hinweis.andere_sportart" to "Als andere Sportart aufgezeichnet",
    "ref.hinweis.deutlich_vorn" to "Deutlich vor Platz 2",
    "ref.hinweis.gemeldet" to "Gemeldet",
