private fun etexteFI(): Map<String, String> = mapOf(
    "imp.ai1" to "yksittäisten sessioiden analysointi (virheiden etsintä, uskottavuustarkistus)",
    "imp.ai2" to "tunnistusmalliemme parantaminen (pumppaus- ja on-foil-tunnistus)",
    "imp.ai3" to "sovelluksen kehittäminen",
    "imp.ai4" to "puuttuvien foilien ja stabilaattoreiden selvittäminen luetteloon",
    "imp.aiIntro" to "Analysointiin ja kehitykseen käytämme Anthropicin tekoälyavustajaa Claudea. Sessio- ja raakadataa, palautetta ja chat-viestejä — myös yksityisviestejä — voidaan siirtää Anthropicille ja käsitellä siellä näihin tarkoituksiin:",
    "imp.aiNote" to "Anthropic käsittelee sisällön toimeksiannostamme; voimassa olevien API-ehtojen mukaan sitä ei käytetä heidän kielimalliensa kouluttamiseen. Käsittely voi tapahtua Yhdysvalloissa. Avustaja voi vastata chatissa omalla nimellään (tili “Claude Code AI”). Katso Anthropicin <a href=\"https://www.anthropic.com/legal/privacy\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-brand-400 hover:underline\">tietosuojakäytäntö</a>.",
    "imp.aiTitle" to "Tekoälyapu (Anthropic Claude)",
    "imp.apple1" to "<b>Käyttöoikeus:</b> sähköpostiosoitteesi (tarvittaessa Applen anonymisoima „Piilota sähköpostini“ -välitysosoite), nimesi (vain kertaalleen ensimmäisen kirjautumisen yhteydessä, jos jaat sen) ja Applen käyttäjä-ID.",
    "imp.apple2" to "<b>Käyttö:</b> yksinomaan Pumpfoil-tilisi luomiseen ja kirjautumiseen.",
    "imp.apple3" to "Ei luovutusta kolmansille, ei mainontaa, ei tekoäly-/ML-koulutusta. Applen puoleisesta käsittelystä vastaa Apple oman tietosuojakäytäntönsä mukaisesti.",
    "imp.appleIntro" to "Kun kirjaudut Applella, käsittelemme yksinomaan seuraavia tietoja:",
    "imp.appleTitle" to "Apple-kirjautuminen („Kirjaudu Applella“)",
    "imp.community1" to "<b>Näyttönimi</b> ja <b>profiilikuva</b> (jos asetettu; ilman näyttönimeä sessio näkyy ilman nimeä).",
    "imp.community2" to "<b>Kaikki sessiot, joissa foiling tunnistettu</b>: päivä/kellonaika, <b>spotti</b> (vesistön nimi OpenStreetMapista), <b>kartta/GPS-reitti</b> (eli <u>missä</u> foilattiin), lenkkien määrä, matka, nopeus, syke, pump-/liukuarvot ja ladatut <b>kuvat</b>.",
    "imp.community3" to "<b>Ennätykset &amp; tulostaulukot</b> (nimi, arvo, spotti, sessioiden/lenkkien/spottien määrä).",
    "imp.community4" to "<b>Tykkäykset</b> (määrä) ja „vaikuttaa epäaidolta“/„sopimaton“-äänten <b>määrä</b>.",
    "imp.community5" to "<b>Paikalla-tila</b>: vihreä piste profiilikuvassasi, kun sovellus tai sivusto on auki. Tallennetaan vain viimeisimmän toimintasi aika (minuutin tarkkuudella). Voit poistaa sen käytöstä profiilissa.",
    "imp.community6" to "<b>Kommentit</b> sessioiden alla näyttönimen, profiilikuvan ja ajan kanssa. Session omistaja voi poistaa kommentit käytöstä profiilissaan ja poistaa muiden kommentteja sessionsa alta; omia kommenttejasi voit muokata tai poistaa tunnin ajan. Ne poistetaan kokonaan tilisi mukana.",
    "imp.community7" to "<b>Tiimit</b>: jäsenyytesi ja roolisi (jäsenluettelon näkyvyyden päättää tiimin johto), sijoituksesi tiimien tulostauluissa ja tapahtumamerkit profiilisivullasi. Lisätietoja kohdassa ”Tiimit”.",
    "imp.community8" to "<b>Chatit</b>: spottichatteja voivat lukea kaikki kirjautuneet, näyttönimen ja profiilikuvan kera. Tiimichattia lukevat vain tiimin aktiiviset jäsenet, yksityisviestejä vain kaksi osapuolta. Voit estää kenet tahansa.",
    "imp.communityIntro" to "Tilin voi luoda kuka tahansa. Kirjautuneena näkee <b>kaikilta</b> käyttäjiltä:",
    "imp.communityNote" to "Sessiot <b>eivät ole anonyymejä</b> — ne on liitetty henkilöön näyttönimen kautta. Voit poistaa minkä tahansa session milloin tahansa yksitellen; vain itse <b>piilottamasi</b> sessiot eivät näy yhteisölistoissa (myös pelkät GPS-sessiot näytetään).",
    "imp.communityTitle" to "👥 Näkyy jokaiselle rekisteröityneelle (yhteisö)",
    "imp.conn1" to "Linkityksessä sinut ohjataan kyseiselle palveluntarjoajalle ja kirjaudut siellä (OAuth). Saamme pääsytokenin sekä jakamasi harjoitus-/workout-datan (mm. GPS-reitti, aika, syke).",
    "imp.conn2" to "Nämä tiedot tuodaan yksinomaan omina sessioinasi ja käsitellään kuten muutkin sessiosi.",
    "imp.conn3" to "Linkityksen voi peruuttaa milloin tahansa kohdassa „Linkitetyt tilit“ — tällöin tallennettu token poistetaan.",
    "imp.connIntro" to "Valinnaisesti ja vain nimenomaisella toiminnallasi voit linkittää kolmannen osapuolen tilin tuodaksesi aktiviteetteja:",
    "imp.connTitle" to "Linkitetyt tilit (Polar, COROS, Suunto)",
    "imp.fb1" to "<b>Pääsy:</b> sähköpostiosoitteesi, etunimesi ja Facebook-käyttäjätunnuksesi. Sukunimeä tai profiilikuvaa emme hae.",
    "imp.fb2" to "<b>Käyttö:</b> ainoastaan Pumpfoil-tilisi luomiseen ja kirjautumiseen sekä etunimesi näyttämiseen sovelluksessa.",
    "imp.fb3" to "Muihin Facebook-tietoihin <b>ei ole pääsyä</b> — ei kaverilistaan, ei julkaisuihin, ei kuviin, ei sivuihin.",
    "imp.fb4" to "Näitä tietoja <b>ei luovuteta kolmansille</b>, ei käytetä mainontaan eikä tekoäly- tai koneoppimismallien kouluttamiseen.",
    "imp.fb5" to "Tällä sivustolla ei ole <b>yhtään Facebook-skriptiä eikä pikseliä</b>. Kirjautuminen on uudelleenohjaus, joka käynnistyy vasta kun painat painiketta — sitä ennen Facebookilla ei ole mitään tekemistä käyntisi kanssa.",
    "imp.fbIntro" to "Jos kirjaudut Facebook-tililläsi, käsittelemme ainoastaan seuraavia tietoja:",
    "imp.fbNote" to "Jos poistat pumpfoil.orgin Facebook-asetuksistasi, poistamme yhteyden automaattisesti; Pumpfoil-tilisi säilyy. Pyynnön tilan näet sivulla <a href=\"/datenloeschung\" class=\"text-brand-400 hover:underline\">Tietojen poisto</a>, ja voit poistaa tilisi kokonaan itse milloin tahansa profiilissa.",
    "imp.fbTitle" to "Facebook-kirjautuminen (”Jatka Facebookilla”)",
    "imp.friends1" to "Ystävät näkevät koko profiilisivusi, myös osiot, jotka olet piilottanut profiilissa, ja painosi.",
    "imp.friends2" to "Kun pumppaat, he näkevät millä spotilla ja saavat ilmoituksen, vaikka olisit piilottanut itsesi spottikartalta. Sessiolistassa ja tulostauluissa on näkymä vain ystäville.",
    "imp.friends3" to "Piilotetut paikat pysyvät piilossa, raakadatasi pysyy yksityisenä. Sinä näet saman heistä. Jos jompikumpi lopettaa ystävyyden, kumpikaan ei enää näe toisen ystävätietoja.",
    "imp.friendsTitle" to "🤝 Ystäväsi (vasta kun molemmat ovat hyväksyneet)",
    "imp.garmin1" to "<b>Mitkä tiedot:</b> vain aktiviteetit, jotka tallennat yhdistämisen jälkeen – reitti, aika, nopeus, syke ja, jos kello on sen tallentanut, kiihtyvyys. Hylkäämme aktiviteetit ilman GPS:ää, elleivät ne kuulu oman kellosovelluksemme tallenteeseen. Valitset itse kohdassa ”Kello ja tilit”, mitkä profiilit tulevat. Emme hae vanhempia aktiviteetteja emmekä terveystietoja (uni, stressi, askeleet …).",
    "imp.garmin2" to "<b>Mihin:</b> laskujesi tunnistamiseen ja näyttämiseen sinulle, henkilökohtaisten ennätysten, spottien ja yhteisön tulostaulujen kanssa. Siellä ne näkyvät kirjautuneille käyttäjille kuten muutkin sessiosi.",
    "imp.garmin2b" to "Julkisissa tiimien tulostauluissa ja globaaleissa tapahtumissa sija, näyttönimi ja arvo näkyvät myös kirjautumatta (ks. ”Julkinen” yllä).",
    "imp.garmin3" to "<b>Kuka ne saa:</b> ei kukaan muu kuin me. Ne tallennetaan palvelimellemme Hetzner Online GmbH:lla (tietojenkäsittelysopimus, katso yllä). Emme myy Garmin-tietoja emmekä luovuta niitä kolmansille osapuolille.",
    "imp.garmin4" to "<b>Ei tekoälyä:</b> Garmin-tietoja ei lähetetä automaattisesti tekoälypalveluihin eikä niitä käytetä tekoälymallien kouluttamiseen tai arviointiin. Analyysi tehdään palvelimellamme omalla koodilla. Vain jos pyydät meiltä nimenomaan apua tiettyyn sessioon, juuri sitä sessiota voidaan tarkastella osana tekoälytukea (katso alla).",
    "imp.garmin5" to "<b>Oikeutesi:</b> voit milloin tahansa katsoa sessioitasi, ladata ne tiedostona, poistaa ne yksitellen tai poistaa kaiken painikkeella ”Poista tili”. Irrotat tilin kohdassa ”Kello ja tilit” tai Garmin Connectissa; poistamme silloin tallennetun käyttöoikeustunnuksen.",
    "imp.garminIntro" to "Jos yhdistät Garmin Connect -tilisi (vapaaehtoista, kohdassa ”Kello ja tilit”), lisäksi pätee:",
    "imp.garminTitle" to "Garmin Connect",
    "imp.gh1" to "Repositoriossa on myös kuvakaappauksia sovelluksista. Niissä voi näkyä se, mitä kirjautuneet jäsenet sovelluksessa näkevät, esimerkiksi ajajien näyttönimiä ennätyksissä tai kellonäkymien tekijöinä sekä spottien nimiä.",
    "imp.gh2" to "Jos et halua nimesi näkyvän siellä, kirjoita meille, niin teemme sen tunnistamattomaksi nykyisissä tiedostoissa. Vanhemmat versiot säilyvät repositorion historiassa, ellei historiaa kirjoiteta uudelleen.",
    "imp.gh3" to "pumpfoil.org vain linkittää GitHubiin eikä lataa sieltä mitään. github.comissa sovelletaan GitHubin tietosuojaselostetta.",
    "imp.gh4" to "Pumpfoilia kehitetään tekoälyavustaja Clauden avulla, joka julkaisee lähdekoodin muutokset itsenäisesti GitHubissa. Käyttäjätiedot eivät kuulu sinne, eikä niitä koskaan ladata sinne tarkoituksella; jokainen julkaisu tarkistetaan automaattisesti. Silti ei voida sulkea pois, että osia niistä päätyy vahingossa julkisiksi, esimerkiksi näyttönimiä, sessioiden paikkoja ja aikoja tai anturitietoja (GPS-reittejä, liiketietoja, sykettä). Mikä on kerran ollut GitHubissa, on voitu kopioida, eikä sitä voi enää kokonaan perua. <b>Jos et halua ottaa tätä riskiä, älä tallenna tai lataa sessioita Pumpfoililla.</b>",
    "imp.ghIntro" to "Pumpfoil on avointa lähdekoodia. Lähdekoodi, dokumentaatio ja muutosloki ovat julkisesti GitHubissa (github.com/kechel/pumpfoil, GitHub, Inc.:n palvelu):",
    "imp.ghTitle" to "Lähdekoodi GitHubissa",
    "imp.google1" to "<b>Käyttöoikeus (Data Accessed):</b> sähköpostiosoitteesi, etunimesi ja Google-tili-ID (sub).",
    "imp.google2" to "<b>Käyttö (Data Usage):</b> yksinomaan Pumpfoil-tilisi luomiseen ja kirjautumiseen sekä etunimesi näyttämiseen sovelluksessa.",
    "imp.google3" to "<b>Ei pääsyä</b> muihin Google-palveluihin tai -tietoihin (ei Google Drive, Gmail, kalenteri tms.).",
    "imp.google4" to "Näitä tietoja <b>ei luovuteta kolmansille</b>, niitä ei käytetä mainontaan eikä tekoäly-/ML-mallien kouluttamiseen.",
    "imp.googleIntro" to "Kun kirjaudut Google-tililläsi (Google Sign-In / OAuth), käsittelemme yksinomaan seuraavia Googlen käyttäjätietoja:",
    "imp.googleNote" to "Google-rajapinnoista saatujen tietojen käyttö noudattaa <a href=\"https://developers.google.com/terms/api-services-user-data-policy\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-brand-400 hover:underline\">Google API Services User Data Policya</a>, mukaan lukien Limited Use -vaatimukset.",
    "imp.googleTitle" to "Google-kirjautuminen (Googlen käyttäjätiedot)",
    "imp.host1" to "<b><a href=\"https://smartkomm.de/\" target=\"_blank\" rel=\"noopener noreferrer\">SmartKomm GmbH</a></b> tarjoaa palvelimen (virtuaalikoneen) <b>maksutta</b>; sen toimitusjohtaja ylläpitää tätä projektia yksityisesti. Pumpfoil.orgista ja kaikista tiedoista vastaa yksinomaan julkaisutiedoissa mainittu ylläpitäjä.",
    "imp.host2" to "Palvelin sijaitsee yrityksellä <b><a href=\"https://www.hetzner.com\" target=\"_blank\" rel=\"noopener noreferrer\">Hetzner Online GmbH</a></b>. Hetznerin kanssa on tehty <b>GDPR:n 28 artiklan mukainen tietojenkäsittelysopimus</b>.",
    "imp.hostTitle" to "Palvelin ja ylläpito",
    "imp.huawei1" to "<b>Siirto:</b> kellosovellus lähettää tallenteen (GPS-reitti, aika, liiketiedot, syke) HUAWEI Healthin kautta Android-puhelimesi Pumpfoil-sovellukseen (HUAWEI Wear Engine), joka lataa sen pumpfoil.orgiin. HUAWEI WATCH 3, 4 ja 5 voivat myös ladata suoraan, kun ne on yhdistetty koodilla.",
    "imp.huawei2" to "<b>Pääsy puhelimessa:</b> vain perustiedot pariliitetyistä HUAWEI-kelloistasi (nimi, yhteyden tila, onko Pumpfoil-kellosovellus asennettu). Emme lue tietoja HUAWEI ID:stäsi, HUAWEI Healthista tai muista sovelluksista.",
    "imp.huawei3" to "Tallenteet tallennetaan vain omina sessioinasi ja niitä käsitellään kuten muitakin sessioitasi. Ei luovutusta kolmansille osapuolille, ei mainontaa.",
    "imp.huawei4" to "Voit peruuttaa pääsyn milloin tahansa: Pumpfoil-sovelluksessa HUAWEI-kellon kortilla (”Katkaise yhteys”) tai HUAWEI Healthissa. Huawei vastaa omalla puolellaan tapahtuvasta käsittelystä oman tietosuojakäytäntönsä mukaisesti.",
    "imp.huaweiIntro" to "Kun tallennat Pumpfoil-sovelluksella HUAWEI-kellolla, tallenne tulee meille puhelimesi kautta:",
    "imp.huaweiTitle" to "HUAWEI-kellot (HUAWEI Health / Wear Engine)",
    "imp.intro" to "Tämä sovellus on yhteisö: foil-sessiot jaetaan muiden kanssa. Tässä kerrotaan tarkalleen, mitkä tiedot näkyvät kenellekin.",
    "imp.map1" to "<b>Katukartta</b> tulee <b>OpenStreetMapilta</b>. Kun kartta näytetään, selaimesi lataa karttaruudut suoraan heidän palvelimiltaan, jolloin välittyvät IP-osoitteesi ja näkyvä karttaosuus. Palveluntarjoaja: OpenStreetMap Foundation, Yhdistynyt kuningaskunta.",
    "imp.map2" to "Jos vaihdat kartan painikkeella <b>satelliittinäkymään</b>, ilmakuvat tulevat <b>Esriltä</b> (Esri, Maxar, Earthstar Geographics) — sekin suoraan heidän palvelimiltaan ja sekin IP-osoitteesi kanssa. Näin käy <b>vain</b>, jos vaihdat näkymää; valintasi muistetaan paikallisesti laitteellasi.",
    "imp.mapApple" to "<b>iPhone- ja Apple Watch -sovelluksessa</b> sekä kartta ETTÄ ilmakuvat tulevat <b>Apple Kartoista</b>, eivät OpenStreetMapilta tai Esriltä. Kartan näyttäminen lähettää näkyvän alueen Applelle; siitä vastaa Apple oman tietosuojakäytäntönsä mukaisesti. <b>Android-sovellus</b> toimii kuten selain: katukartta OpenStreetMapilta, ilmakuvat Esriltä.",
    "imp.mapSpots" to "<b>Spottien nimet</b>: palvelimemme hakee paikka- ja vesistönimet spotin koordinaateille OpenStreetMap-palveluista (Nominatim ja Overpass, mukaan lukien VK/mail.ru:n ylläpitämä Overpass-peili). Vain spotin koordinaatit lähetetään, ei tilin tietoja. Merellä oleville spoteille otamme lähimmän paikkakunnan <b>GeoNames</b>-luettelosta (geonames.org, CC BY 4.0), joka on omalla palvelimellamme.",
    "imp.mapTitle" to "Kartat",
    "imp.mcp1" to "Halutessasi voit antaa tekoälyohjelmalle (esim. Anthropicin Claude) lukuoikeuden omiin tallennuksiisi, vain jos sallit sen nimenomaisesti suostumussivullamme (OAuth).",
    "imp.mcp2" to "Ohjelma saa vain lukea, ja vain omia tallennuksiasi, summiasi ja parhaita arvojasi varusteineen. Ei muiden ajajien tietoja, ei kuvia, videoita, viestejä tai arvioita, ei hylättyjä tai poistettuja tallennuksia.",
    "imp.mcp3" to "Mitä ohjelma hakee, sen tarjoaja käsittelee omien ehtojensa mukaan. Voit päättää pääsyn milloin tahansa kohdassa ”Liitetyt tilit”.",
    "imp.mcpTitle" to "Tekoälyohjelmat omilla tallennuksillasi (tekoälypääsy)",
    "imp.operator1" to "Sähköpostiosoitteet, kaikki raakadata, laitelinkitykset ja tekniset palvelinlokit.",
    "imp.operator2" to "Salasanat tallennetaan vain suolattuna hashina (PBKDF2) — en näe niitäkään selkokielisenä.",
    "imp.operator3" to "Teknisesti ylläpitäjä voi nähdä kaiken tallennetun sisällön, myös yksityisviestit ja tiimichatit (ks. myös ”Tekoälyapu”).",
    "imp.operatorTitle" to "🛠 Vain ylläpitäjä (Jan)",
    "imp.owner1" to "Sessioidesi <b>raakadata</b> (yksittäiset GPS-pisteet, 25 Hz kiihtyvyys) — esim. merkitsemistä varten.",
    "imp.owner2" to "Merkinnät, rajaus, uudelleenanalysointi, kuvien lataus/poisto.",
    "imp.owner3" to "<b>Sähköpostiosoitteesi</b> ja tiliasetukset — eivät koskaan näy muille käyttäjille.",
    "imp.owner4" to "Vain sinä näet, kuka tykkäsi sessiostasi; muut näkevät vain määrän. Sitä, kuka ilmoitti ”näyttää väärennetyltä” tai ”sopimaton”, ei näytetä kenellekään.",
    "imp.owner5" to "<b>Käynnissä olevat tallennukset</b>: jos puhelimen tallennin lähettää livenä (profiilin kytkin ”Lähetä livenä”, voi kytkeä pois), GPS- ja liiketiedot tulevat palvelimellemme jo tallennuksen aikana. Sen, että ja mistä asti tallennus on käynnissä, näet muilla laitteillasi ja kelloissasi. Nimelläsi sen näkevät sinun lisäksesi vain vahvistetut ystäväsi, spotin kera (ks. ”Ystäväsi”); ilman nimeä spottisi voi muuttua vihreäksi spottikartalla (seuraava kohta). Kelloille ”tallentaa luultavasti” päätellään pelkästään siitä, milloin kellosovellus viimeksi otti yhteyttä. Itse sessio näkyy muille vasta, kun se on päättynyt.",
    "imp.owner6" to "<b>Aktiiviset spotit</b>: spottikartta värittää vihreiksi spotit, joissa joku luultavasti pumppaa juuri nyt. Käytämme spottia 1 km:n säteellä käynnissä olevasta puhelintallennuksestasi tai sijainnista, jonka kellosi ilmoittaa kerran käynnistettäessä (vain spotti tallennetaan, ei sijaintia), ja latauksen jälkeen sessiosi spottia. Jos lähellä ei ole spottia, sessiossa ei ole tunnistettuja ajoja tai poistat sen, et näy aktiivisena. Yksittäinen spotti muuttuu vihreäksi vain, jos siellä on ollut vähintään 4 ajajaa viimeisen 180 päivän aikana; pienemmät spotit värittävät vain ryhmän, ja vain jos alueen spoteilla oli yli 5 ajajaa viimeisen 90 päivän aikana. Nimiä ei näytetä. Voit poistaa tämän käytöstä profiilissa (”Näytä minut spottikartalla”).",
    "imp.ownerTitle" to "🔒 Vain sinä itse (session omistaja)",
    "imp.privacyText" to "Kaikki ladatut tiedot säilytetään pysyvästi. Poistaaksesi käytä profiilisi „Poista tili“ -painiketta (web-sovellus tai iOS-/Android-sovellus) — se poistaa tilisi kaikkine sessioineen, raakadatoineen ja kuvineen lopullisesti. Tiedonsiirto on salattua (HTTPS).",
    "imp.privacyTitle" to "Tietojen poisto",
    "imp.public1" to "<b>Ladatut kuvat</b> ja <b>profiilikuvat</b>: kuvatiedostot ovat satunnaisen, arvaamattoman linkin takana. Kuka tahansa, joka tietää tämän linkin (esim. edelleen lähetettynä), voi avata kuvan ilman tiliä. EXIF-/GPS-tiedot kuvista poistetaan latauksen yhteydessä.",
    "imp.public2" to "Itse web-sovellus ja kello-sovelluksen lataus.",
    "imp.public3" to "<b>Julkiset tiimien tulostaulut</b>: jos tiimin johto tekee sen tulostaulut julkisiksi, kuka tahansa näkee ne kirjautumatta, myös jaettujen tapahtumalinkkien kautta: sijan, näyttönimen, nimikirjaimet ja arvon. Sessiot, spotit ja profiilikuvat näkevät vain kirjautuneet. Hakukoneet eivät indeksoi tiimisivuja.",
    "imp.public4" to "<b>Globaalit tapahtumat</b> (pumpfoil.org): niihin osallistuu automaattisesti jokainen, jolla on sopivia sessioita, ilman ilmoittautumista. Niiden tulostaulut näkyvät tapahtumalinkin kautta myös kirjautumatta (sija, näyttönimi, nimikirjaimet, arvo), ja arvosi lasketaan tiimiesi tiimipisteisiin. Voit kytkeä tämän pois profiilissa kohdassa ”Yksityisyys” valinnalla ”Älä osallistu globaaleihin tapahtumiin”; silloin katoat myös jo päättyneistä tapahtumista.",
    "imp.publicTitle" to "🌍 Julkinen (kuka tahansa netissä, ilman kirjautumista)",
    "imp.teams1" to "<b>Sinä päätät</b>, liitytkö tiimiin; liittymisikkuna kertoo etukäteen, ovatko sen tulostaulut juuri nyt julkisia. Voit erota milloin tahansa, ja katoat silloin heti tiimin tulostauluilta. Vain jo päättyneissä tapahtumissa pysyt jäädytetyssä tuloksessa.",
    "imp.teams2" to "<b>Tiimin johto päättää</b>, ovatko tulostaulut julkisia, kuka näkee jäsenluettelon (vain jäsenet vai kaikki kirjautuneet) ja mitä tulostauluja ja tapahtumia on. Liittymällä hyväksyt, että tulostaulut voivat olla julkisia, vaikka ne eivät nyt olisi; silloin näyttönimesi ja sijasi näkyvät kirjautumatta. Yksittäisiä jäseniä ei voi piilottaa.",
    "imp.teams3" to "Kaikki sessiosi lasketaan, myös liittymistä edeltävät; tapahtumissa vain aikaikkunan sisällä olevat. Tapahtuman sijat 1–3 saavat merkin profiilisivulleen.",
    "imp.teams4" to "Liittymispyynnön yhteydessä johto ja moderaattorit näkevät, millä spoteilla ja missä lajeissa olet tähän asti liikkunut (vain sessioiden määrän).",
    "imp.teams5" to "Tiimi näkyy ulospäin nimen, kuvauksen, vaakunan ja kuvan kanssa vasta hyväksyntämme jälkeen. Jos tilisi poistetaan, katoat kaikista tiimeistä ja tulostauluilta, myös jäädytetyistä tapahtumatuloksista.",
    "imp.teamsTitle" to "🏁 Tiimit: mitä sinä päätät ja mitä tiimin johto päättää",
    "imp.title" to "Julkaisutiedot",
    "imp.werteText" to "Lupaamme tasan yhden asian: palvelimella toimii GitHubin julkinen lähdekoodi. Näytetään se, mitä se laskee ladatuista tiedoista, vaikka luvut olisivat vääriä tai odottamattomia. Emme lupaa, että mittaukset, sessiot, ennätykset, tulostaulut ja tapahtumat ovat oikein tai manipuloimattomia.",
    "imp.werteTitle" to "Mittaukset ja näytettävät tiedot",
    "imp.whoSees" to "Tietosuoja",
    "imp.yt1" to "Etusivulla näytämme YouTube-kanavamme esikatselukuvia. Ne tarjoillaan <b>oman palvelimemme</b> kautta — sivun latautuessa ei synny <b>mitään</b> yhteyttä Googleen eikä <b>mitään</b> evästeitä aseteta.",
    "imp.yt2" to "Vasta kun <b>klikkaat</b> videota, ladataan YouTube-soitin (tila „laajennettu tietosuoja“, youtube-nocookie.com). Silloin Google/YouTube saa IP-osoitteesi ja voi asettaa evästeitä. Klikkauksella annat tähän suostumuksesi.",
    "imp.ytNote" to "Tarjoaja: Google Ireland Ltd. Tarkemmin <a href=\"https://policies.google.com/privacy\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-brand-400 hover:underline\">Googlen tietosuojaselosteessa</a>.",
    "imp.ytTitle" to "Upotetut YouTube-videot",
