    "ref.aufhebenFrage" to "Perutaanko korjaus? Ajajan {fahrer} ajo {lauf} lasketaan taas, ja ajajalle ilmoitetaan.",
    "ref.bearbeiten" to "Muokkaa",
    "ref.bearbeitetAm" to "muokattu {am}",
    "ref.bestaetigen" to "Tämä poistaa ajajan {fahrer} ajon {lauf} tuloslistalta, näyttää syyn ja julkisen kommentin tapahtumasivulla ja ilmoittaa ajajalle.",
