private fun etexteNL(): Map<String, String> = mapOf(
    "imp.ai1" to "analyse van afzonderlijke sessies (foutopsporing, plausibiliteitscontrole)",
    "imp.ai2" to "verbetering van onze detectiemodellen (pump- en on-foil-detectie)",
    "imp.ai3" to "verdere ontwikkeling van de app",
    "imp.ai4" to "onderzoek naar ontbrekende foils en stabilizers voor de catalogus",
    "imp.aiIntro" to "Voor analyse en ontwikkeling gebruiken we de AI-assistent Claude van Anthropic. Sessie- en ruwe data, feedback en chatberichten — ook directe berichten — kunnen naar Anthropic worden verzonden en daar worden verwerkt, voor deze doeleinden:",
    "imp.aiNote" to "Anthropic verwerkt de inhoud in onze opdracht; volgens de geldende API-voorwaarden wordt deze niet gebruikt om hun taalmodellen te trainen. De verwerking kan in de VS plaatsvinden. De assistent kan in de chat onder eigen naam antwoorden (account “Claude Code AI”). Zie het <a href=\"https://www.anthropic.com/legal/privacy\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-brand-400 hover:underline\">privacybeleid van Anthropic</a>.",
    "imp.aiTitle" to "AI-ondersteuning (Anthropic Claude)",
    "imp.apple1" to "<b>Toegang:</b> je e-mailadres (eventueel het door Apple geanonimiseerde ‘Hide My Email'-relay-adres), je naam (alleen eenmalig bij de eerste login, als je die deelt) en de Apple-gebruikers-ID.",
    "imp.apple2" to "<b>Gebruik:</b> uitsluitend voor het aanmaken van en inloggen op je Pumpfoil-account.",
    "imp.apple3" to "Geen doorgifte aan derden, geen reclame, geen AI-/ML-training. Voor de verwerking aan Apple-zijde is Apple verantwoordelijk volgens hun privacybeleid.",
    "imp.appleIntro" to "Als je inlogt met Apple, verwerken we uitsluitend de volgende gegevens:",
    "imp.appleTitle" to "Apple-login (‘Inloggen met Apple')",
    "imp.community1" to "<b>Weergavenaam</b> en <b>profielfoto</b> (indien ingesteld; zonder weergavenaam verschijnt de sessie zonder naam).",
    "imp.community2" to "<b>Alle sessies met gedetecteerd foilen</b>: datum/tijd, <b>spot</b> (waternaam uit OpenStreetMap), de <b>kaart/GPS-route</b> (dus <u>waar</u> is gefoild), aantal runs, afstand, snelheid, hartslag, pomp-/glijwaarden en de geüploade <b>foto's</b>.",
    "imp.community3" to "<b>Records &amp; ranglijsten</b> (naam, waarde, spot, aantal sessies/runs/spots).",
    "imp.community4" to "<b>Likes</b> (aantal) en het <b>aantal</b> stemmen ‘lijkt nep'/‘ongepast'.",
    "imp.community5" to "<b>Online-status</b>: een groen stipje bij je profielfoto zolang je de app of de website open hebt. Alleen het tijdstip van je laatste activiteit wordt opgeslagen (op de minuut). Uit te zetten in je profiel.",
    "imp.community6" to "<b>Reacties</b> onder sessies, met weergavenaam, profielfoto en tijdstip. De eigenaar van een sessie kan reacties in zijn profiel uitzetten en reacties van anderen onder zijn sessie verwijderen; je eigen reacties kun je een uur lang bewerken of verwijderen. Ze worden volledig verwijderd met je account.",
    "imp.community7" to "<b>Teams</b>: je lidmaatschappen met rol (wie de ledenlijst ziet, bepaalt de teamleiding), je plaatsen in teamranglijsten en eventbadges op je profielpagina. Details onder „Teams”.",
    "imp.community8" to "<b>Chats</b>: spotchats kunnen alle ingelogde gebruikers lezen, met weergavenaam en profielfoto. De teamchat lezen alleen actieve leden van het team, directe berichten alleen de twee betrokkenen. Je kunt iedereen blokkeren.",
    "imp.communityIntro" to "Iedereen kan een account aanmaken. Ingelogd zie je van <b>alle</b> gebruikers:",
    "imp.communityNote" to "Sessies zijn <b>niet anoniem</b> — ze zijn via de weergavenaam aan de persoon gekoppeld. Je kunt elke sessie op elk moment afzonderlijk verwijderen; alleen door jou <b>verborgen</b> sessies verschijnen niet in de community-lijsten (ook pure GPS-sessies worden getoond).",
    "imp.communityTitle" to "👥 Zichtbaar voor iedere geregistreerde persoon (community)",
    "imp.conn1" to "Bij het koppelen word je doorgestuurd naar de betreffende aanbieder en log je daar in (OAuth). Wij ontvangen een toegangstoken en de door jou vrijgegeven trainings-/workoutgegevens (o.a. GPS-route, tijd, hartslag).",
    "imp.conn2" to "Deze gegevens worden uitsluitend als je eigen sessies geïmporteerd en net als je overige sessies behandeld.",
    "imp.conn3" to "De koppeling is op elk moment onder ‘Gekoppelde accounts' in te trekken — daarbij wordt het opgeslagen token verwijderd.",
    "imp.connIntro" to "Optioneel en alleen op jouw uitdrukkelijke actie kun je een account van een derde partij koppelen om activiteiten te importeren:",
    "imp.connTitle" to "Gekoppelde accounts (Polar, COROS, Suunto)",
    "imp.fb1" to "<b>Toegang:</b> je e-mailadres, je voornaam en je Facebook-gebruikers-ID. Je achternaam en profielfoto halen we niet op.",
    "imp.fb2" to "<b>Gebruik:</b> uitsluitend om je Pumpfoil-account aan te maken en aan te melden en om je voornaam in de app te tonen.",
    "imp.fb3" to "Er is <b>geen toegang</b> tot andere Facebook-gegevens — geen vriendenlijst, geen berichten, geen foto’s, geen pagina’s.",
    "imp.fb4" to "Deze gegevens worden <b>niet aan derden doorgegeven</b>, niet voor reclame gebruikt en niet gebruikt om AI-/ML-modellen te trainen.",
    "imp.fb5" to "Op deze website draait <b>geen Facebook-script en geen pixel</b>. Het aanmelden is een doorverwijzing die pas start als je op de knop drukt — daarvoor heeft Facebook niets met je bezoek te maken.",
    "imp.fbIntro" to "Als je je aanmeldt met je Facebook-account, verwerken we uitsluitend de volgende gegevens:",
    "imp.fbNote" to "Verwijder je pumpfoil.org in je Facebook-instellingen, dan wissen we de koppeling automatisch; je Pumpfoil-account blijft bestaan. De stand van zo’n verzoek vind je op <a href=\"/datenloeschung\" class=\"text-brand-400 hover:underline\">Gegevens verwijderen</a>, en je account helemaal verwijderen kun je altijd zelf in je profiel.",
    "imp.fbTitle" to "Facebook-aanmelding (“Doorgaan met Facebook”)",
    "imp.friends1" to "Vrienden zien je hele profielpagina, ook onderdelen die je in je profiel hebt verborgen, en je gewicht.",
    "imp.friends2" to "Als je aan het pumpen bent, zien ze op welke spot en krijgen ze een melding, ook als je jezelf op de spotkaart hebt verborgen. Sessielijst en ranglijsten hebben een weergave met alleen vrienden.",
    "imp.friends3" to "Verborgen plekken blijven verborgen, je ruwe gegevens blijven privé. Jij ziet hetzelfde van hen. Beëindigt een van jullie de vriendschap, dan ziet vanaf dat moment niemand meer de vriendengegevens van de ander.",
    "imp.friendsTitle" to "🤝 Je vrienden (pas als jullie allebei hebben ingestemd)",
    "imp.garmin1" to "<b>Welke gegevens:</b> alleen activiteiten die je na het koppelen opneemt – route, tijd, snelheid, hartslag en, als het horloge die heeft opgenomen, de versnelling. Activiteiten zonder gps gooien we weg, tenzij ze bij een opname van onze eigen horloge-app horen. Welke profielen binnenkomen kies je onder „Horloge & accounts”. Oudere activiteiten en gezondheidsgegevens (slaap, stress, stappen …) halen we niet op.",
    "imp.garmin2" to "<b>Waarvoor:</b> om je ritten te herkennen en aan je te tonen, met persoonlijke records, spots en de ranglijsten van de community. Daar zijn ze net als je andere sessies zichtbaar voor ingelogde gebruikers.",
    "imp.garmin2b" to "In openbare teamranglijsten en globale events verschijnen plaats, weergavenaam en waarde ook zonder inloggen (zie „Openbaar” hierboven).",
    "imp.garmin3" to "<b>Wie ze krijgt:</b> niemand behalve wij. Ze worden opgeslagen op onze server bij Hetzner Online GmbH (verwerkersovereenkomst, zie boven). We verkopen Garmin-gegevens niet en geven ze niet door aan derden.",
    "imp.garmin4" to "<b>Geen AI:</b> Garmin-gegevens worden niet automatisch naar AI-diensten gestuurd en niet gebruikt om AI-modellen te trainen of te beoordelen. De analyse draait op onze server met eigen code. Alleen als je ons uitdrukkelijk om hulp vraagt bij een bepaalde sessie, kan die ene sessie bekeken worden in het kader van de AI-ondersteuning (zie onder).",
    "imp.garmin5" to "<b>Je rechten:</b> je kunt je sessies altijd bekijken, als bestand downloaden, één voor één verwijderen of alles wissen met ‘Account verwijderen’. Je ontkoppelt het account onder ‘Horloge & accounts’ of in Garmin Connect; dan verwijderen we het opgeslagen toegangstoken.",
    "imp.garminIntro" to "Als je je Garmin Connect-account koppelt (vrijwillig, onder ‘Horloge & accounts’), geldt daarnaast:",
    "imp.garminTitle" to "Garmin Connect",
    "imp.gh1" to "De repository bevat ook screenshots van de apps. Die kunnen tonen wat ingelogde leden in de app zien, bijvoorbeeld weergavenamen van riders in records of als makers van horloge-layouts, en spotnamen.",
    "imp.gh2" to "Wil je je naam daar niet zien, schrijf ons dan; we maken hem in de huidige bestanden onherkenbaar. Oudere versies blijven in de geschiedenis van de repository staan zolang die niet wordt herschreven.",
    "imp.gh3" to "pumpfoil.org linkt alleen naar GitHub en laadt daar niets van. Op github.com geldt de privacyverklaring van GitHub.",
    "imp.gh4" to "Pumpfoil wordt ontwikkeld met hulp van de AI-assistent Claude, die wijzigingen in de broncode zelfstandig op GitHub publiceert. Gebruikersgegevens horen daar niet thuis en worden nooit bewust geüpload; elke publicatie wordt daar automatisch op gecontroleerd. Toch is niet uit te sluiten dat er per ongeluk delen openbaar worden, bijvoorbeeld weergavenamen, plaatsen en tijden van sessies of sensorgegevens (GPS-routes, bewegingsgegevens, hartslag). Wat eenmaal op GitHub stond, kan door anderen gekopieerd zijn en is dan niet meer volledig terug te halen. <b>Wil je dit risico niet lopen, neem dan geen sessies op met Pumpfoil en upload er geen.</b>",
    "imp.ghIntro" to "Pumpfoil is open source. De broncode, de documentatie en de changelog staan openbaar op GitHub (github.com/kechel/pumpfoil, een dienst van GitHub, Inc.):",
    "imp.ghTitle" to "Broncode op GitHub",
    "imp.google1" to "<b>Toegang (Data Accessed):</b> je e-mailadres, je voornaam en je Google-account-ID (sub).",
    "imp.google2" to "<b>Gebruik (Data Usage):</b> uitsluitend voor het aanmaken van en inloggen op je Pumpfoil-account en voor het tonen van je voornaam in de app.",
    "imp.google3" to "Er is <b>geen toegang</b> tot andere Google-diensten of -gegevens (geen Google Drive, Gmail, Agenda e.d.).",
    "imp.google4" to "Deze gegevens worden <b>niet aan derden doorgegeven</b>, niet voor reclame gebruikt en niet voor het trainen van AI-/ML-modellen ingezet.",
    "imp.googleIntro" to "Als je inlogt met je Google-account (Google Sign-In / OAuth), verwerken we uitsluitend de volgende Google-gebruikersgegevens:",
    "imp.googleNote" to "Het gebruik van informatie uit Google-API's voldoet aan de <a href=\"https://developers.google.com/terms/api-services-user-data-policy\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-brand-400 hover:underline\">Google API Services User Data Policy</a>, inclusief de Limited-Use-vereisten.",
    "imp.googleTitle" to "Google-login (Google-gebruikersgegevens)",
    "imp.host1" to "<b><a href=\"https://smartkomm.de/\" target=\"_blank\" rel=\"noopener noreferrer\">SmartKomm GmbH</a></b> stelt de server (een virtuele machine) <b>gratis</b> beschikbaar; de directeur ervan beheert dit project privé. Alleen de beheerder uit het colofon is verantwoordelijk voor pumpfoil.org en alle gegevens.",
    "imp.host2" to "De server staat bij <b><a href=\"https://www.hetzner.com\" target=\"_blank\" rel=\"noopener noreferrer\">Hetzner Online GmbH</a></b>. Met Hetzner is een <b>verwerkersovereenkomst volgens art. 28 AVG</b> gesloten.",
    "imp.hostTitle" to "Server en hosting",
    "imp.huawei1" to "<b>Overdracht:</b> de horloge-app stuurt je opname (GPS-route, tijd, bewegingsgegevens, hartslag) via HUAWEI Health naar de Pumpfoil-app op je Android-telefoon (HUAWEI Wear Engine), die hem naar pumpfoil.org uploadt. HUAWEI WATCH 3, 4 en 5 kunnen ook direct uploaden nadat je ze met een code hebt gekoppeld.",
    "imp.huawei2" to "<b>Toegang op de telefoon:</b> alleen basisgegevens van je gekoppelde HUAWEI-horloges (naam, verbindingsstatus, of de Pumpfoil-app op het horloge staat). We lezen geen gegevens uit je HUAWEI ID, uit HUAWEI Health of uit andere apps.",
    "imp.huawei3" to "De opnames worden uitsluitend als je eigen sessies opgeslagen en behandeld zoals je andere sessies. Geen delen met derden, geen reclame.",
    "imp.huawei4" to "Je kunt de toegang altijd intrekken: in de Pumpfoil-app op de kaart van het HUAWEI-horloge (“Ontkoppelen”) of in HUAWEI Health. Huawei is verantwoordelijk voor de verwerking aan Huawei-zijde volgens zijn eigen privacybeleid.",
    "imp.huaweiIntro" to "Als je met de Pumpfoil-app op een HUAWEI-horloge opneemt, bereikt de opname ons via je telefoon:",
    "imp.huaweiTitle" to "HUAWEI-horloges (HUAWEI Health / Wear Engine)",
    "imp.intro" to "Deze app is een community: foil-sessies worden met anderen gedeeld. Hier staat precies welke gegevens voor wie zichtbaar zijn.",
    "imp.map1" to "De <b>stratenkaart</b> komt van <b>OpenStreetMap</b>. Bij het tonen van een kaart laadt je browser de kaarttegels rechtstreeks van hun servers; daarbij worden je IP-adres en het getoonde gebied doorgegeven. Aanbieder: OpenStreetMap Foundation, Verenigd Koninkrijk.",
    "imp.map2" to "Schakel je met de knop op de kaart over naar <b>Satelliet</b>, dan komen de luchtfoto's van <b>Esri</b> (Esri, Maxar, Earthstar Geographics) — ook rechtstreeks van hun servers en ook met je IP-adres. Dat gebeurt <b>alleen</b> als je omschakelt; je keuze wordt lokaal op je apparaat onthouden.",
    "imp.mapApple" to "In de <b>iPhone- en Apple Watch-app</b> komen zowel de kaart ALS de luchtfoto's van <b>Apple Kaarten</b>, niet van OpenStreetMap of Esri. Bij het tonen van een kaart stuurt je apparaat het getoonde gebied naar Apple; Apple is daarvoor verantwoordelijk volgens hun privacybeleid. De <b>Android-app</b> werkt zoals de browser: stratenkaart van OpenStreetMap, luchtfoto's van Esri.",
    "imp.mapSpots" to "<b>Spotnamen</b>: onze server zoekt plaats- en waternamen voor de coördinaten van een spot op bij OpenStreetMap-diensten (Nominatim en Overpass, waaronder de Overpass-mirror van VK/mail.ru). Alleen de coördinaten van de spot worden verstuurd, geen accountgegevens. Voor spots op zee nemen we de dichtstbijzijnde plaats uit <b>GeoNames</b> (geonames.org, CC BY 4.0), een lijst op onze eigen server.",
    "imp.mapTitle" to "Kaarten",
    "imp.mcp1" to "Optioneel kun je een AI-programma (bijv. Claude van Anthropic) leestoegang geven tot je eigen opnames, alleen als je dat op onze toestemmingspagina uitdrukkelijk toestaat (OAuth).",
    "imp.mcp2" to "Het programma mag alleen lezen, en alleen je eigen opnames, totalen en beste waarden inclusief uitrusting. Geen gegevens van andere riders, geen foto's, video's, berichten of beoordelingen, geen uitgesloten of verwijderde opnames.",
    "imp.mcp3" to "Wat het programma ophaalt, verwerkt de aanbieder ervan volgens zijn eigen voorwaarden. Je kunt de toegang altijd beëindigen onder „Gekoppelde accounts”.",
    "imp.mcpTitle" to "AI-programma's met je eigen opnames (AI-toegang)",
    "imp.operator1" to "E-mailadressen, alle ruwe data, apparaatkoppelingen en technische serverlogs.",
    "imp.operator2" to "Wachtwoorden worden alleen als gezouten hash (PBKDF2) opgeslagen — ook ik zie ze niet in klare tekst.",
    "imp.operator3" to "Technisch kan de beheerder alle opgeslagen inhoud inzien, ook directe berichten en teamchats (zie ook „AI-ondersteuning”).",
    "imp.operatorTitle" to "🛠 Alleen de beheerder (Jan)",
    "imp.owner1" to "<b>Ruwe data</b> van je sessies (afzonderlijke GPS-punten, 25 Hz-versnelling) — bijv. voor het labelen.",
    "imp.owner2" to "Labels, trimmen, opnieuw analyseren, foto's uploaden/verwijderen.",
    "imp.owner3" to "Je <b>e-mailadres</b> en accountinstellingen — nooit zichtbaar voor andere gebruikers.",
    "imp.owner4" to "Alleen jij ziet wie je sessie heeft geliket; anderen zien alleen het aantal. Wie „lijkt nep” of „ongepast” meldde, wordt aan niemand getoond.",
    "imp.owner5" to "<b>Lopende opnames</b>: uploadt je telefoonrecorder live (schakelaar „Live uploaden” in je profiel, uit te zetten), dan komen GPS- en bewegingsgegevens al tijdens de opname op onze server. Dat en sinds wanneer er wordt opgenomen, zie je op je andere apparaten en je horloges. Met je naam zien dat naast jou alleen je bevestigde vrienden, inclusief de spot (zie „Je vrienden”); zonder naam kan je spot groen worden op de spotkaart (volgende punt). Bij horloges leiden we „neemt waarschijnlijk op” alleen af uit het moment waarop de horloge-app zich het laatst meldde. De sessie zelf verschijnt pas voor anderen als ze klaar is.",
    "imp.owner6" to "<b>Actieve spots</b>: de spotkaart kleurt spots groen waar waarschijnlijk nu iemand pompt. We nemen de spot binnen 1 km van je lopende telefoonopname of van de positie die je horloge één keer bij het starten doorgeeft (alleen de spot wordt opgeslagen, niet de positie), en na het uploaden de spot van je sessie. Is er geen spot in de buurt, heeft de sessie geen herkende runs of verwijder je haar, dan tel je niet als actief. Een losse spot wordt alleen groen bij minstens 4 riders in de afgelopen 180 dagen; kleinere spots kleuren alleen een groep, en alleen als de spots in die omgeving de afgelopen 90 dagen meer dan 5 riders hadden. Er worden geen namen getoond. Je kunt dit uitzetten in je profiel (‘Toon mij op de spotkaart’).",
    "imp.ownerTitle" to "🔒 Alleen jijzelf (eigenaar van de sessie)",
    "imp.privacyText" to "Alle geüploade gegevens worden permanent opgeslagen. Om te verwijderen gebruik je de knop ‘Account verwijderen' in je profiel (web-app of iOS-/Android-app) — die verwijdert je account met alle sessies, ruwe data en foto's definitief. De overdracht verloopt versleuteld (HTTPS).",
    "imp.privacyTitle" to "Gegevens verwijderen",
    "imp.public1" to "<b>Geüploade foto's</b> en <b>profielfoto's</b>: de afbeeldingsbestanden staan onder een willekeurige, niet te raden link. Wie deze link kent (bijv. doorgestuurd), kan de afbeelding ook zonder account openen. EXIF-/GPS-gegevens in foto's worden bij het uploaden verwijderd.",
    "imp.public2" to "De web-app zelf en de download van de horloge-app.",
    "imp.public3" to "<b>Openbare teamranglijsten</b>: zet de leiding van een team de ranglijsten openbaar, dan ziet iedereen ze zonder in te loggen, ook via gedeelde eventlinks: plaats, weergavenaam, initialen en waarde. Sessies, spots en profielfoto's zien alleen ingelogde gebruikers. Zoekmachines nemen teampagina's niet op.",
    "imp.public4" to "<b>Globale events</b> van pumpfoil.org: wie passende sessies heeft, doet automatisch mee, zonder zich aan te melden. De ranglijsten zijn via de eventlink ook zonder inloggen zichtbaar (plaats, weergavenaam, initialen, waarde), en je waarden tellen mee voor de teamstand van je teams. Uitzetten kan in je profiel onder „Privacy” met „Niet meedoen aan globale events”; dan verdwijn je ook uit events die al voorbij zijn.",
    "imp.publicTitle" to "🌍 Openbaar (iedereen op internet, zonder login)",
    "imp.teams1" to "<b>Jij beslist</b> of je lid wordt van een team; het aanmeldvenster vertelt je vooraf of de ranglijsten op dat moment openbaar zijn. Je kunt altijd uittreden en verdwijnt dan meteen uit de ranglijsten van het team. Alleen in events die al voorbij zijn, blijf je in de bevroren uitslag staan.",
    "imp.teams2" to "<b>De teamleiding beslist</b> of de ranglijsten openbaar zijn, wie de ledenlijst ziet (alleen leden of alle ingelogde gebruikers) en welke ranglijsten en events er zijn. Door lid te worden, ga je ermee akkoord dat de ranglijsten openbaar kunnen zijn, ook als ze dat nu niet zijn; je weergavenaam en plaats zijn dan zonder inloggen zichtbaar. Afzonderlijke leden kunnen niet worden verborgen.",
    "imp.teams3" to "Al je sessies tellen mee, ook die van vóór je lidmaatschap; bij events alleen die binnen het tijdvak. Plaats 1 tot 3 van een event krijgen een badge op hun profielpagina.",
    "imp.teams4" to "Bij een aanmeldverzoek zien leiding en moderators op welke spots en in welke sporten je tot nu toe actief was (alleen het aantal sessies).",
    "imp.teams5" to "Een team verschijnt pas naar buiten met naam, beschrijving, wapen en afbeelding na onze goedkeuring. Wordt je account verwijderd, dan verdwijn je uit alle teams en ranglijsten, ook uit bevroren eventuitslagen.",
    "imp.teamsTitle" to "🏁 Teams: wat jij beslist en wat de teamleiding bepaalt",
    "imp.title" to "Colofon",
    "imp.werteText" to "We beloven precies één ding: op de server draait de openbare broncode van GitHub. Getoond wordt wat die uit de geüploade gegevens berekent, ook als de getallen fout of onverwacht zijn. We beloven niet dat meetwaarden, sessies, records, ranglijsten en events kloppen of niet zijn gemanipuleerd.",
    "imp.werteTitle" to "Meetwaarden en weergaven",
    "imp.whoSees" to "Privacy",
    "imp.yt1" to "Op de startpagina tonen we voorbeeldafbeeldingen van ons YouTube-kanaal. Deze worden via <b>onze eigen server</b> geleverd — bij het laden van de pagina is er <b>geen</b> contact met Google en worden er <b>geen</b> cookies geplaatst.",
    "imp.yt2" to "Pas wanneer je een video <b>aanklikt</b>, wordt de YouTube-player (modus ‘uitgebreide privacy', youtube-nocookie.com) geladen. Dan ontvangt Google/YouTube je IP-adres en kan het cookies plaatsen. Met de klik stem je daarmee in.",
    "imp.ytNote" to "Aanbieder: Google Ireland Ltd. Meer in het <a href=\"https://policies.google.com/privacy\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-brand-400 hover:underline\">privacybeleid van Google</a>.",
    "imp.ytTitle" to "Ingesloten YouTube-video's",
    "ref.ablehnen" to "Afwijzen",
    "ref.alsEntwurf" to "Opslaan als concept",
    "ref.anlegen" to "Correctie voorbereiden",
    "ref.aufheben" to "Intrekken",
    "ref.aufhebenFrage" to "Correctie intrekken? {lauf} van {fahrer} telt weer mee en de rider krijgt een melding.",
    "ref.bearbeiten" to "Bewerken",
