private fun etexteCS(): Map<String, String> = mapOf(
    "imp.ai1" to "analýza jednotlivých session (hledání chyb, kontrola věrohodnosti)",
    "imp.ai2" to "zlepšování našich detekčních modelů (rozpoznávání pumpování a jízdy na foilu)",
    "imp.ai3" to "další vývoj aplikace",
    "imp.ai4" to "dohledávání chybějících foilů a stabilizátorů do katalogu",
    "imp.aiIntro" to "K analýze a vývoji používáme asistenta AI Claude od Anthropic. Data ze session i nezpracovaná data, zpětná vazba a zprávy z chatu — včetně přímých zpráv — mohou být předány společnosti Anthropic a tam zpracovány, a to k těmto účelům:",
    "imp.aiNote" to "Anthropic zpracovává obsah z našeho pověření; podle platných podmínek API se nepoužívá k trénování jejich jazykových modelů. Zpracování může probíhat v USA. Asistent může v chatu odpovídat pod vlastním jménem (účet „Claude Code AI“). Více v <a href=\"https://www.anthropic.com/legal/privacy\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-brand-400 hover:underline\">zásadách ochrany osobních údajů Anthropic</a>.",
    "imp.aiTitle" to "Podpora AI (Anthropic Claude)",
    "imp.apple1" to "<b>Přístup:</b> tvoji e-mailovou adresu (případně anonymizovanou relay adresu „Hide My Email“ od Apple), tvé jméno (jen jednou při první registraci, pokud jsi ho poskytl) a Apple ID uživatele.",
    "imp.apple2" to "<b>Použití:</b> výhradně k vytvoření a přihlášení tvého účtu Pumpfoil.",
    "imp.apple3" to "Žádné předávání třetím stranám, žádná reklama, žádné trénování AI/ML. Za zpracování na straně Apple odpovídá Apple podle svých zásad ochrany osobních údajů.",
    "imp.appleIntro" to "Když se přihlásíš přes Apple, zpracováváme výhradně následující data:",
    "imp.appleTitle" to "Přihlášení přes Apple („Přihlásit se přes Apple“)",
    "imp.community1" to "<b>Zobrazované jméno</b> a <b>profilový obrázek</b> (pokud je nastaven; bez zobrazovaného jména se vyjížďky zobrazí bez jména).",
    "imp.community2" to "<b>Všechny vyjížďky s rozpoznaným foilingem</b>: datum/čas, <b>spot</b> (název vody z OpenStreetMap), <b>mapu/GPS trasu</b> (tedy <u>kde</u> ses foilil), počet jízd, vzdálenost, rychlost, tep, hodnoty pumpování/klouzání a nahrané <b>fotky</b>.",
    "imp.community3" to "<b>Rekordy a žebříčky</b> (jméno, hodnota, spot, počet vyjížděk/jízd/spotů).",
    "imp.community4" to "<b>To se mi líbí</b> (počet) a <b>počet</b> hlasů „působí neuvěřitelně“/„nevhodné“.",
    "imp.community5" to "<b>Stav online</b>: zelená tečka u profilového obrázku, dokud máš otevřenou aplikaci nebo web. Ukládá se jen čas tvé poslední aktivity (na minutu). Lze vypnout v profilu.",
    "imp.community6" to "<b>Komentáře</b> pod sessions se zobrazovaným jménem, profilovým obrázkem a časem. Vlastník session může komentáře v profilu vypnout a mazat cizí komentáře pod svou session; vlastní komentáře můžeš hodinu upravovat nebo smazat. Se zrušením účtu se úplně smažou.",
    "imp.community7" to "<b>Týmy</b>: tvá členství s rolí (kdo vidí seznam členů, určuje vedení týmu), tvá umístění v týmových žebříčcích a odznaky z eventů na tvé profilové stránce. Podrobnosti v části „Týmy“.",
    "imp.community8" to "<b>Chaty</b>: chaty spotů čtou všichni přihlášení, se zobrazovaným jménem a profilovým obrázkem. Týmový chat čtou jen aktivní členové týmu, přímé zprávy jen oba zúčastnění. Zablokovat můžeš kohokoli.",
    "imp.communityIntro" to "Účet si může založit kdokoli. Po přihlášení vidíš u <b>všech</b> uživatelů:",
    "imp.communityNote" to "Vyjížďky <b>nejsou anonymní</b> — jsou přiřazeny osobě přes její zobrazované jméno. Každou vyjížďku můžeš kdykoli jednotlivě smazat; jen vyjížďky, které jsi <b>skryl(a)</b>, se v komunitních seznamech neobjeví (zobrazují se i čistě GPS vyjížďky).",
    "imp.communityTitle" to "👥 Viditelné pro každou registrovanou osobu (komunita)",
    "imp.conn1" to "Při propojení budeš přesměrován k danému poskytovateli a tam se přihlásíš (OAuth). Získáme přístupový token a tebou uvolněná tréninková/workout data (mj. GPS trasu, čas, tepovou frekvenci).",
    "imp.conn2" to "Tato data se importují výhradně jako tvé vlastní vyjížďky a zachází se s nimi jako s ostatními tvými vyjížďkami.",
    "imp.conn3" to "Propojení lze kdykoli zrušit v části „Propojené účty“ — přitom se uložený token smaže.",
    "imp.connIntro" to "Volitelně a jen na tvou výslovnou akci můžeš propojit účet třetí strany pro import aktivit:",
    "imp.connTitle" to "Propojené účty (Polar, COROS, Suunto)",
    "imp.fb1" to "<b>Přístup:</b> tvoji e-mailovou adresu, tvoje křestní jméno a tvoje uživatelské ID na Facebooku. Příjmení ani profilovou fotku nestahujeme.",
    "imp.fb2" to "<b>Použití:</b> výhradně k vytvoření a přihlášení tvého účtu Pumpfoil a k zobrazení tvého křestního jména v aplikaci.",
    "imp.fb3" to "K dalším údajům z Facebooku <b>nemáme žádný přístup</b> — žádný seznam přátel, žádné příspěvky, žádné fotky, žádné stránky.",
    "imp.fb4" to "Tyto údaje <b>nepředáváme třetím stranám</b>, nepoužíváme je pro reklamu ani k trénování modelů AI či strojového učení.",
    "imp.fb5" to "Na tomto webu neběží <b>žádný skript Facebooku ani pixel</b>. Přihlášení je přesměrování, které se spustí až ve chvíli, kdy stiskneš tlačítko — do té doby nemá Facebook s tvojí návštěvou nic společného.",
    "imp.fbIntro" to "Když se přihlásíš svým účtem na Facebooku, zpracováváme výhradně tyto údaje:",
    "imp.fbNote" to "Když pumpfoil.org odebereš v nastavení Facebooku, propojení smažeme automaticky; tvůj účet Pumpfoil zůstane. Stav takové žádosti najdeš na stránce <a href=\"/datenloeschung\" class=\"text-brand-400 hover:underline\">Smazání údajů</a> a celý účet můžeš kdykoli smazat sám v profilu.",
    "imp.fbTitle" to "Přihlášení přes Facebook („Pokračovat přes Facebook“)",
    "imp.friends1" to "Přátelé vidí celou tvou profilovou stránku, i části, které máš v profilu skryté, a tvou váhu.",
    "imp.friends2" to "Když právě pumpuješ, vidí, na kterém spotu, a dostanou upozornění, i když ses na mapě spotů skryl. Seznam sessions a žebříčky mají zobrazení jen s přáteli.",
    "imp.friends3" to "Skrytá místa zůstávají skrytá, tvá surová data zůstávají soukromá. Ty vidíš totéž o nich. Když jeden z vás přátelství ukončí, od té chvíle už nikdo nevidí přátelské údaje toho druhého.",
    "imp.friendsTitle" to "🤝 Tví přátelé (až když oba souhlasíte)",
    "imp.garmin1" to "<b>Jaká data:</b> jen aktivity, které nahraješ po propojení – trasa, čas, rychlost, tepová frekvence a, pokud je hodinky zaznamenaly, zrychlení. Aktivity bez GPS zahazujeme, pokud nepatří k záznamu z naší vlastní aplikace pro hodinky. Které profily přicházejí, si zvolíš v „Hodinky a účty“. Starší aktivity ani zdravotní data (spánek, stres, kroky …) nestahujeme.",
    "imp.garmin2" to "<b>K čemu:</b> abychom rozpoznali tvé jízdy a ukázali ti je, s osobními rekordy, spoty a žebříčky komunity. Tam jsou viditelné přihlášeným uživatelům stejně jako tvé ostatní session.",
    "imp.garmin2b" to "Ve veřejných týmových žebříčcích a globálních eventech se pořadí, zobrazované jméno a hodnota zobrazují i bez přihlášení (viz „Veřejné“ výše).",
    "imp.garmin3" to "<b>Kdo je dostane:</b> nikdo kromě nás. Ukládají se na náš server u Hetzner Online GmbH (smlouva o zpracování, viz výše). Data z Garminu neprodáváme ani nepředáváme třetím stranám.",
    "imp.garmin4" to "<b>Žádná AI:</b> data z Garminu se automaticky neposílají službám AI a nepoužívají se k trénování ani hodnocení modelů AI. Vyhodnocení běží na našem serveru vlastním kódem. Jen pokud nás výslovně požádáš o pomoc s konkrétní session, může být právě tato jedna session prohlédnuta v rámci podpory AI (viz níže).",
    "imp.garmin5" to "<b>Tvá práva:</b> své session můžeš kdykoli prohlížet, stáhnout jako soubor, mazat jednotlivě nebo vše odstranit tlačítkem „Smazat účet“. Propojení zrušíš v části „Hodinky a účty“ nebo v Garmin Connect; uložený přístupový token pak smažeme.",
    "imp.garminIntro" to "Pokud propojíš svůj účet Garmin Connect (dobrovolně, v části „Hodinky a účty“), platí navíc:",
    "imp.garminTitle" to "Garmin Connect",
    "imp.gh1" to "V repozitáři jsou i snímky obrazovky aplikací. Mohou ukazovat, co vidí přihlášení členové, například zobrazovaná jména jezdců v rekordech nebo jako autorů rozložení pro hodinky a názvy spotů.",
    "imp.gh2" to "Pokud tam své jméno nechceš mít, napiš nám a v aktuálních souborech ho znečitelníme. Starší verze zůstávají v historii repozitáře, dokud se nepřepíše.",
    "imp.gh3" to "pumpfoil.org na GitHub jen odkazuje a nic z něj nenačítá. Na github.com platí zásady ochrany osobních údajů GitHubu.",
    "imp.gh4" to "Pumpfoil se vyvíjí s pomocí AI asistenta Claude, který změny zdrojového kódu sám zveřejňuje na GitHubu. Uživatelská data tam nepatří a nikdy se tam úmyslně nenahrávají; každé zveřejnění se na to automaticky kontroluje. Přesto nelze vyloučit, že se jejich části omylem stanou veřejnými, například zobrazovaná jména, místa a časy sessions nebo data ze senzorů (GPS trasy, pohybová data, tep). Co jednou bylo na GitHubu, mohli si jiní zkopírovat a nelze to pak už úplně vzít zpět. <b>Pokud toto riziko nechceš podstoupit, nenahrávej s Pumpfoilem žádné sessions.</b>",
    "imp.ghIntro" to "Pumpfoil je open source. Zdrojový kód, dokumentace a changelog jsou veřejně na GitHubu (github.com/kechel/pumpfoil, služba společnosti GitHub, Inc.):",
    "imp.ghTitle" to "Zdrojový kód na GitHubu",
    "imp.google1" to "<b>Přístup (Data Accessed):</b> tvoji e-mailovou adresu, křestní jméno a ID účtu Google (sub).",
    "imp.google2" to "<b>Použití (Data Usage):</b> výhradně k vytvoření a přihlášení tvého účtu Pumpfoil a k zobrazení tvého křestního jména v aplikaci.",
    "imp.google3" to "Nedochází k <b>žádnému přístupu</b> k dalším službám nebo datům Google (žádný Google Drive, Gmail, kalendář apod.).",
    "imp.google4" to "Tato data se <b>nepředávají třetím stranám</b>, nepoužívají k reklamě ani k trénování AI/ML modelů.",
    "imp.googleIntro" to "Když se přihlásíš svým účtem Google (Google Sign-In / OAuth), zpracováváme výhradně následující uživatelská data Google:",
    "imp.googleNote" to "Použití informací z Google API odpovídá <a href=\"https://developers.google.com/terms/api-services-user-data-policy\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-brand-400 hover:underline\">Google API Services User Data Policy</a>, včetně požadavků Limited Use.",
    "imp.googleTitle" to "Přihlášení přes Google (uživatelská data Google)",
    "imp.host1" to "<b><a href=\"https://smartkomm.de/\" target=\"_blank\" rel=\"noopener noreferrer\">SmartKomm GmbH</a></b> poskytuje server (virtuální stroj) <b>bezplatně</b>; její jednatel provozuje tento projekt soukromě. Za pumpfoil.org a všechna data odpovídá výhradně provozovatel uvedený v tiráži.",
    "imp.host2" to "Server je umístěn u <b><a href=\"https://www.hetzner.com\" target=\"_blank\" rel=\"noopener noreferrer\">Hetzner Online GmbH</a></b>. S firmou Hetzner je uzavřena <b>smlouva o zpracování osobních údajů podle čl. 28 GDPR</b>.",
    "imp.hostTitle" to "Server a hosting",
    "imp.huawei1" to "<b>Přenos:</b> aplikace v hodinkách posílá záznam (trasa GPS, čas, pohybová data, tep) přes HUAWEI Health do aplikace Pumpfoil v tvém telefonu s Androidem (HUAWEI Wear Engine), která ho nahraje na pumpfoil.org. HUAWEI WATCH 3, 4 a 5 mohou po propojení kódem nahrávat i přímo.",
    "imp.huawei2" to "<b>Přístup v telefonu:</b> jen základní údaje o spárovaných hodinkách HUAWEI (název, stav připojení, zda je v hodinkách nainstalovaná aplikace Pumpfoil). Nečteme žádná data z tvého HUAWEI ID, z HUAWEI Health ani z jiných aplikací.",
    "imp.huawei3" to "Záznamy ukládáme výhradně jako tvé vlastní session a zacházíme s nimi jako s ostatními. Žádné předávání třetím stranám, žádná reklama.",
    "imp.huawei4" to "Přístup můžeš kdykoli odvolat: v aplikaci Pumpfoil na kartě hodinek HUAWEI („Odpojit“) nebo v HUAWEI Health. Za zpracování na straně Huawei odpovídá Huawei podle svých vlastních zásad ochrany osobních údajů.",
    "imp.huaweiIntro" to "Pokud nahráváš aplikací Pumpfoil na hodinkách HUAWEI, záznam se k nám dostane přes tvůj telefon:",
    "imp.huaweiTitle" to "Hodinky HUAWEI (HUAWEI Health / Wear Engine)",
    "imp.intro" to "Tato aplikace je komunita: foil vyjížďky se sdílejí s ostatními. Zde je přesně popsáno, která data jsou pro koho viditelná.",
    "imp.map1" to "<b>Silniční mapa</b> pochází z <b>OpenStreetMap</b>. Při zobrazení mapy načte tvůj prohlížeč mapové dlaždice přímo z jejich serverů; přitom se přenáší tvoje IP adresa a zobrazený výřez. Poskytovatel: OpenStreetMap Foundation, Spojené království.",
    "imp.map2" to "Když tlačítkem na mapě přepneš na <b>satelit</b>, letecké snímky přicházejí od <b>Esri</b> (Esri, Maxar, Earthstar Geographics) — rovněž přímo z jejich serverů a rovněž s tvojí IP adresou. Stane se to <b>jen</b> tehdy, když přepneš; tvoje volba se uloží lokálně ve tvém zařízení.",
    "imp.mapApple" to "V <b>aplikaci pro iPhone a Apple Watch</b> pochází mapa I letecké snímky z <b>Apple Map</b>, nikoli z OpenStreetMap nebo Esri. Zobrazení mapy odešle zobrazený výřez Applu; odpovědnost za to nese Apple podle svých zásad ochrany soukromí. <b>Aplikace pro Android</b> funguje stejně jako prohlížeč: silniční mapa z OpenStreetMap, letecké snímky z Esri.",
    "imp.mapSpots" to "<b>Názvy spotů</b>: náš server vyhledává názvy míst a vodních ploch k souřadnicím spotu ve službách OpenStreetMap (Nominatim a Overpass, včetně zrcadla Overpass provozovaného VK/mail.ru). Odesílají se jen souřadnice spotu, žádné údaje o účtu. U spotů na moři bereme nejbližší obec z <b>GeoNames</b> (geonames.org, CC BY 4.0), seznamu uloženého na našem serveru.",
    "imp.mapTitle" to "Mapy",
    "imp.mcp1" to "Volitelně můžeš programu AI (např. Claude od Anthropic) dát přístup ke čtení svých vlastních záznamů, jen pokud to výslovně povolíš na naší stránce souhlasu (OAuth).",
    "imp.mcp2" to "Program smí jen číst, a jen tvé vlastní záznamy, součty a nejlepší hodnoty včetně vybavení. Žádná data jiných jezdců, žádné fotky, videa, zprávy ani hodnocení, žádné vyřazené ani smazané záznamy.",
    "imp.mcp3" to "Co program načte, zpracovává jeho poskytovatel podle vlastních podmínek. Přístup můžeš kdykoli ukončit v „Propojené účty“.",
    "imp.mcpTitle" to "Programy AI s tvými vlastními záznamy (přístup AI)",
    "imp.operator1" to "E-mailové adresy, všechna surová data, propojení zařízení a technické serverové logy.",
    "imp.operator2" to "Hesla se ukládají jen jako solený hash (PBKDF2) — ani já je nevidím v čitelné podobě.",
    "imp.operator3" to "Technicky může provozovatel nahlížet do veškerého uloženého obsahu, včetně přímých zpráv a týmových chatů (viz také „Podpora AI“).",
    "imp.operatorTitle" to "🛠 Jen provozovatel (Jan)",
    "imp.owner1" to "<b>Surová data</b> tvých vyjížděk (jednotlivé GPS body, zrychlení 25 Hz) — např. pro označování.",
    "imp.owner2" to "Štítky, oříznutí, opětovná analýza, nahrávání/mazání fotek.",
    "imp.owner3" to "Tvoje <b>e-mailová adresa</b> a nastavení účtu — nikdy viditelné pro jiné uživatele.",
    "imp.owner4" to "Kdo dal tvé vyjížďce lajk, vidíš jen ty; ostatní vidí jen počet. Kdo nahlásil „vypadá falešně“ nebo „nevhodné“, se nikomu nezobrazuje.",
    "imp.owner5" to "<b>Probíhající záznamy</b>: pokud záznamník v telefonu nahrává živě (přepínač „Nahrávat živě“ v profilu, lze vypnout), GPS a pohybová data jdou na náš server už během záznamu. Že a od kdy se nahrává, vidíš na svých dalších zařízeních a hodinkách. Se jménem to kromě tebe vidí jen tví potvrzení přátelé, včetně spotu (viz „Tví přátelé“); bez jména může tvůj spot zezelenat na mapě spotů (další bod). U hodinek odvozujeme „nejspíš nahrává“ jen z okamžiku, kdy se aplikace v hodinkách naposledy ozvala. Samotná session se ostatním zobrazí až po dokončení.",
    "imp.owner6" to "<b>Aktivní spoty</b>: mapa spotů barví zeleně spoty, kde teď pravděpodobně někdo pumpuje. Použijeme spot do 1 km od tvého probíhajícího nahrávání telefonem nebo od polohy, kterou hodinky jednou nahlásí při spuštění (ukládá se jen spot, ne poloha), a po nahrání spot tvé session. Když poblíž žádný spot není, session nemá žádné rozpoznané jízdy nebo ji smažeš, nepočítáš se jako aktivní. Jednotlivý spot zezelená jen s alespoň 4 jezdci za posledních 180 dní; menší spoty barví jen skupinu, a to jen pokud spoty v okolí měly za posledních 90 dní víc než 5 jezdců. Jména se nezobrazují. Vypnout to můžeš v profilu („Zobrazit mě na mapě spotů“).",
    "imp.ownerTitle" to "🔒 Jen ty sám (vlastník vyjížďky)",
    "imp.privacyText" to "Všechna nahraná data se ukládají trvale. Ke smazání použij prosím tlačítko „Smazat účet“ ve svém profilu (webová aplikace nebo iOS/Android aplikace) — nadobro odstraní tvůj účet se všemi vyjížďkami, surovými daty a fotkami. Přenos probíhá šifrovaně (HTTPS).",
    "imp.privacyTitle" to "Smazání dat",
    "imp.public1" to "<b>Nahrané fotky</b> a <b>profilové obrázky</b>: obrazové soubory leží pod náhodným, neuhodnutelným odkazem. Kdo tento odkaz zná (např. přeposlaný), může obrázek otevřít i bez účtu. EXIF/GPS data ve fotkách se při nahrání odstraňují.",
    "imp.public2" to "Samotná webová aplikace a stažení aplikace pro hodinky.",
    "imp.public3" to "<b>Veřejné žebříčky týmů</b>: když vedení týmu zveřejní jeho žebříčky, vidí je kdokoli bez přihlášení, i přes sdílené odkazy na eventy: pořadí, zobrazované jméno, iniciály a hodnotu. Sessions, spoty a profilové obrázky vidí jen přihlášení. Vyhledávače stránky týmů neindexují.",
    "imp.public4" to "<b>Globální eventy</b> pumpfoil.org: účastní se jich automaticky každý s odpovídajícími sessions, bez přihlašování. Jejich žebříčky jsou přes odkaz na event vidět i bez přihlášení (pořadí, zobrazované jméno, iniciály, hodnota) a tvé hodnoty se počítají do týmového hodnocení tvých týmů. Vypnout to můžeš v profilu v části „Soukromí“ volbou „Neúčastnit se globálních eventů“; pak zmizíš i z již skončených eventů.",
    "imp.publicTitle" to "🌍 Veřejné (kdokoli na internetu, bez přihlášení)",
    "imp.teams1" to "<b>Ty rozhoduješ</b>, zda do týmu vstoupíš; dialog vstupu ti předem řekne, jestli jsou jeho žebříčky právě veřejné. Vystoupit můžeš kdykoli a pak hned zmizíš z žebříčků týmu. Jen v již skončených eventech zůstáváš ve zmrazeném výsledku.",
    "imp.teams2" to "<b>Vedení týmu rozhoduje</b>, zda jsou žebříčky veřejné, kdo vidí seznam členů (jen členové, nebo všichni přihlášení) a jaké žebříčky a eventy existují. Vstupem souhlasíš, že žebříčky mohou být veřejné, i když teď nejsou; pak je tvé zobrazované jméno a umístění vidět bez přihlášení. Jednotlivé členy nelze skrýt.",
    "imp.teams3" to "Počítají se všechny tvé sessions, i ty z doby před vstupem; u eventů jen ty v časovém okně. Místa 1 až 3 v eventu dostanou odznak na své profilové stránce.",
    "imp.teams4" to "Při žádosti o vstup vidí vedení a moderátoři, na kterých spotech a v jakých sportech jsi dosud jezdil (jen počet sessions).",
    "imp.teams5" to "Navenek se tým se jménem, popisem, erbem a obrázkem objeví až po našem schválení. Když je tvůj účet smazán, zmizíš ze všech týmů a žebříčků, i ze zmrazených výsledků eventů.",
    "imp.teamsTitle" to "🏁 Týmy: co rozhoduješ ty a co určuje vedení týmu",
    "imp.title" to "Tiráž",
    "imp.werteText" to "Slibujeme přesně jednu věc: na serveru běží veřejný zdrojový kód z GitHubu. Zobrazuje se to, co spočítá z nahraných dat, i když jsou čísla chybná nebo nečekaná. Neslibujeme, že naměřené hodnoty, sessions, rekordy, žebříčky a eventy jsou správné nebo nebyly zmanipulovány.",
    "imp.werteTitle" to "Naměřené hodnoty a zobrazení",
    "imp.whoSees" to "Ochrana osobních údajů",
    "imp.yt1" to "Na úvodní stránce zobrazujeme náhledy našeho YouTube kanálu. Ty se doručují přes <b>náš vlastní server</b> — při načtení stránky nevzniká <b>žádný</b> kontakt s Google a nenastavují se <b>žádné</b> cookies.",
    "imp.yt2" to "Teprve když na video <b>klikneš</b>, načte se přehrávač YouTube (režim „rozšířená ochrana soukromí“, youtube-nocookie.com). Google/YouTube pak dostane tvoji IP adresu a může nastavit cookies. Kliknutím s tím souhlasíš.",
    "imp.ytNote" to "Poskytovatel: Google Ireland Ltd. Podrobnosti v <a href=\"https://policies.google.com/privacy\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-brand-400 hover:underline\">zásadách ochrany osobních údajů Google</a>.",
    "imp.ytTitle" to "Vložená videa YouTube",
