private fun etextePL(): Map<String, String> = mapOf(
    "imp.ai1" to "Analiza pojedynczych sesji (szukanie błędów, sprawdzanie wiarygodności)",
    "imp.ai2" to "Ulepszanie naszych modeli wykrywania (pompy i jazda na foilu)",
    "imp.ai3" to "Dalszy rozwój aplikacji",
    "imp.ai4" to "Wyszukiwanie brakujących foili i stabilizatorów do katalogu",
    "imp.aiIntro" to "Do analizy i rozwoju korzystamy z asystenta AI Claude firmy Anthropic. Dane sesji i surowe dane, opinie oraz wiadomości z czatu — także wiadomości prywatne — mogą być przekazywane do Anthropic i tam przetwarzane w tych celach:",
    "imp.aiNote" to "Anthropic przetwarza treści na nasze zlecenie; zgodnie z obowiązującymi warunkami API nie są one używane do trenowania ich modeli językowych. Przetwarzanie może odbywać się w USA. Asystent może odpowiadać na czacie pod własną nazwą (konto „Claude Code AI”). Zobacz <a href=\"https://www.anthropic.com/legal/privacy\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-brand-400 hover:underline\">politykę prywatności</a> Anthropic.",
    "imp.aiTitle" to "Wsparcie AI (Anthropic Claude)",
    "imp.apple1" to "<b>Dostęp:</b> Twój adres e-mail (ewentualnie zanonimizowany adres przekierowujący Apple „Hide My Email”), Twoje imię (tylko raz, przy pierwszym logowaniu, jeśli je udostępnisz) oraz identyfikator użytkownika Apple.",
    "imp.apple2" to "<b>Zastosowanie:</b> wyłącznie do założenia konta Pumpfoil i logowania się do niego.",
    "imp.apple3" to "Brak przekazywania osobom trzecim, brak reklam, brak trenowania AI/ML. Za przetwarzanie po stronie Apple odpowiada Apple, zgodnie ze swoją polityką prywatności.",
    "imp.appleIntro" to "Gdy logujesz się przez Apple, przetwarzamy wyłącznie następujące dane:",
    "imp.appleTitle" to "Logowanie Apple („Sign in with Apple”)",
    "imp.community1" to "<b>Nazwę wyświetlaną</b> i <b>zdjęcie profilowe</b> (jeśli ustawione; bez nazwy wyświetlanej sesja pojawia się bez nazwy).",
    "imp.community2" to "<b>Wszystkie sesje z wykrytym foilingiem</b>: datę/godzinę, <b>spot</b> (nazwa akwenu z OpenStreetMap), <b>mapę/ślad GPS</b> (czyli <u>gdzie</u> foilowałeś), liczbę przejazdów, dystans, prędkość, tętno, wartości pomp/szybowania oraz wysłane <b>zdjęcia</b>.",
    "imp.community3" to "<b>Rekordy i rankingi</b> (nazwa, wartość, spot, liczba sesji/przejazdów/spotów).",
    "imp.community4" to "<b>Polubienia</b> (liczba) oraz <b>liczbę</b> głosów „wygląda na fejk”/„nieodpowiednie”.",
    "imp.community5" to "<b>Status online</b>: zielona kropka przy zdjęciu profilowym, gdy masz otwartą aplikację lub stronę. Zapisujemy tylko czas twojej ostatniej aktywności (z dokładnością do minuty). Można to wyłączyć w profilu.",
    "imp.community6" to "<b>Komentarze</b> pod sesjami, z nazwą, zdjęciem profilowym i czasem. Właściciel sesji może wyłączyć komentarze w profilu i usuwać cudze komentarze pod swoją sesją; własne komentarze możesz edytować lub usunąć przez godzinę. Są całkowicie usuwane razem z kontem.",
    "imp.community7" to "<b>Drużyny</b>: twoje członkostwa z rolą (kto widzi listę członków, ustala kierownictwo drużyny), twoje miejsca w rankingach drużyn i odznaki z eventów na twojej stronie profilu. Szczegóły w „Drużyny”.",
    "imp.community8" to "<b>Czaty</b>: czaty spotów czytają wszyscy zalogowani, z nazwą wyświetlaną i zdjęciem profilowym. Czat drużyny czytają tylko aktywni członkowie drużyny, wiadomości prywatne tylko dwie zaangażowane osoby. Możesz zablokować każdego.",
    "imp.communityIntro" to "Konto może założyć każdy. Po zalogowaniu widzisz u <b>wszystkich</b> użytkowników:",
    "imp.communityNote" to "Sesje <b>nie są anonimowe</b> — są powiązane z osobą przez jej nazwę wyświetlaną. Każdą sesję możesz w każdej chwili pojedynczo usunąć; tylko sesje, które <b>ukryjesz</b>, nie pojawiają się na listach społeczności (sesje tylko z GPS też są pokazywane).",
    "imp.communityTitle" to "👥 Widoczne dla każdej zarejestrowanej osoby (społeczność)",
    "imp.conn1" to "Przy łączeniu zostajesz przekierowany do danego dostawcy i logujesz się u niego (OAuth). Otrzymujemy token dostępu oraz udostępnione przez Ciebie dane treningów (w tym ślad GPS, czas, tętno).",
    "imp.conn2" to "Te dane są importowane wyłącznie jako Twoje własne sesje i traktowane jak pozostałe Twoje sesje.",
    "imp.conn3" to "Połączenie możesz w każdej chwili cofnąć w „Połączonych kontach” — zapisany token zostaje wtedy usunięty.",
    "imp.connIntro" to "Opcjonalnie i wyłącznie na Twoje wyraźne działanie możesz połączyć konto innej usługi, aby importować aktywności:",
    "imp.connTitle" to "Połączone konta (Polar, COROS, Suunto)",
    "imp.fb1" to "<b>Dostęp:</b> twój adres e-mail, twoje imię i twój identyfikator użytkownika Facebooka. Nazwiska ani zdjęcia profilowego nie pobieramy.",
    "imp.fb2" to "<b>Wykorzystanie:</b> wyłącznie do utworzenia konta Pumpfoil i logowania oraz do pokazywania twojego imienia w aplikacji.",
    "imp.fb3" to "<b>Nie mamy dostępu</b> do żadnych innych danych z Facebooka — ani listy znajomych, ani postów, ani zdjęć, ani stron.",
    "imp.fb4" to "Tych danych <b>nie przekazujemy osobom trzecim</b>, nie używamy do reklam ani do trenowania modeli AI/ML.",
    "imp.fb5" to "Na tej stronie nie działa <b>żaden skrypt Facebooka ani piksel</b>. Logowanie to przekierowanie, które uruchamia się dopiero po naciśnięciu przycisku — wcześniej Facebook nie ma nic wspólnego z twoją wizytą.",
    "imp.fbIntro" to "Jeśli zalogujesz się swoim kontem na Facebooku, przetwarzamy wyłącznie następujące dane:",
    "imp.fbNote" to "Jeśli usuniesz pumpfoil.org w ustawieniach Facebooka, powiązanie skasujemy automatycznie; twoje konto Pumpfoil pozostaje. Stan takiego zgłoszenia znajdziesz na stronie <a href=\"/datenloeschung\" class=\"text-brand-400 hover:underline\">Usunięcie danych</a>, a całe konto możesz w każdej chwili usunąć sam w profilu.",
    "imp.fbTitle" to "Logowanie przez Facebooka („Kontynuuj przez Facebooka”)",
    "imp.friends1" to "Znajomi widzą całą twoją stronę profilu, także sekcje ukryte w profilu, oraz twoją wagę.",
    "imp.friends2" to "Gdy pompujesz, widzą, na którym spocie, i dostają powiadomienie, nawet jeśli ukryłeś się na mapie spotów. Lista sesji i rankingi mają widok tylko ze znajomymi.",
    "imp.friends3" to "Ukryte miejsca pozostają ukryte, twoje surowe dane pozostają prywatne. Ty widzisz to samo o nich. Jeśli któreś z was zakończy znajomość, od tej chwili nikt nie widzi już danych znajomego drugiej osoby.",
    "imp.friendsTitle" to "🤝 Twoi znajomi (dopiero gdy obie strony się zgodzą)",
    "imp.garmin1" to "<b>Jakie dane:</b> tylko aktywności nagrane po połączeniu konta – trasa, czas, prędkość, tętno oraz, jeśli zegarek je zapisał, przyspieszenie. Aktywności bez GPS odrzucamy, chyba że należą do nagrania z naszej własnej aplikacji na zegarek. Które profile przychodzą, wybierasz w „Zegarek i konta”. Nie pobieramy starszych aktywności ani danych zdrowotnych (sen, stres, kroki …).",
    "imp.garmin2" to "<b>Do czego:</b> by rozpoznać twoje przejazdy i pokazać je tobie, z rekordami osobistymi, spotami i rankingami społeczności. Tam, jak twoje inne sesje, są widoczne dla zalogowanych użytkowników.",
    "imp.garmin2b" to "W publicznych rankingach drużyn i globalnych eventach miejsce, nazwa wyświetlana i wartość pojawiają się także bez logowania (zob. „Publicznie” wyżej).",
    "imp.garmin3" to "<b>Kto je dostaje:</b> nikt poza nami. Są przechowywane na naszym serwerze w Hetzner Online GmbH (umowa powierzenia, zob. wyżej). Nie sprzedajemy danych z Garmina i nie przekazujemy ich osobom trzecim.",
    "imp.garmin4" to "<b>Bez AI:</b> dane z Garmina nie są automatycznie wysyłane do usług AI i nie służą do trenowania ani oceniania modeli AI. Analiza odbywa się na naszym serwerze własnym kodem. Tylko jeśli wyraźnie poprosisz nas o pomoc przy konkretnej sesji, ta jedna sesja może zostać obejrzana w ramach wsparcia AI (zob. niżej).",
    "imp.garmin5" to "<b>Twoje prawa:</b> możesz w każdej chwili oglądać swoje sesje, pobrać je jako plik, usuwać pojedynczo albo usunąć wszystko przyciskiem „Usuń konto”. Połączenie odłączasz w „Zegarek i konta” lub w Garmin Connect; wtedy usuwamy zapisany token dostępu.",
    "imp.garminIntro" to "Jeśli połączysz konto Garmin Connect (dobrowolnie, w „Zegarek i konta”), obowiązuje dodatkowo:",
    "imp.garminTitle" to "Garmin Connect",
    "imp.gh1" to "W repozytorium są też zrzuty ekranu aplikacji. Mogą pokazywać to, co widzą zalogowani członkowie, np. wyświetlane nazwy riderów w rekordach lub jako autorów układów zegarka oraz nazwy spotów.",
    "imp.gh2" to "Jeśli nie chcesz, żeby było tam widać Twoją nazwę, napisz do nas, a uczynimy ją nieczytelną w aktualnych plikach. Starsze wersje pozostają w historii repozytorium, dopóki nie zostanie ona przepisana.",
    "imp.gh3" to "pumpfoil.org tylko odsyła do GitHuba i niczego stamtąd nie wczytuje. Na github.com obowiązuje polityka prywatności GitHuba.",
    "imp.gh4" to "Pumpfoil jest rozwijany z pomocą asystenta AI Claude, który samodzielnie publikuje zmiany w kodzie źródłowym na GitHubie. Dane użytkowników nie powinny się tam znaleźć i nigdy nie są tam celowo wysyłane; każda publikacja jest automatycznie sprawdzana. Mimo to nie można wykluczyć, że ich fragmenty przez pomyłkę staną się publiczne, na przykład nazwy wyświetlane, miejsca i godziny sesji lub dane z czujników (trasy GPS, dane ruchu, tętno). To, co raz trafiło na GitHuba, mogło zostać skopiowane przez innych i nie da się tego już w pełni wycofać. <b>Jeśli nie chcesz podejmować tego ryzyka, nie nagrywaj ani nie przesyłaj sesji przez Pumpfoil.</b>",
    "imp.ghIntro" to "Pumpfoil jest open source. Kod źródłowy, dokumentacja i dziennik zmian są publiczne na GitHubie (github.com/kechel/pumpfoil, usługa GitHub, Inc.):",
    "imp.ghTitle" to "Kod źródłowy na GitHubie",
    "imp.google1" to "<b>Dane, do których mamy dostęp:</b> Twój adres e-mail, Twoje imię oraz identyfikator konta Google (sub).",
    "imp.google2" to "<b>Zastosowanie danych:</b> wyłącznie do założenia konta Pumpfoil i logowania się do niego oraz do pokazania Twojego imienia w aplikacji.",
    "imp.google3" to "<b>Nie ma dostępu</b> do innych usług ani danych Google (żadnego Google Drive, Gmaila, Kalendarza itd.).",
    "imp.google4" to "Te dane <b>nie są przekazywane osobom trzecim</b>, nie służą do reklam ani do trenowania modeli AI/ML.",
    "imp.googleIntro" to "Gdy logujesz się swoim kontem Google (Google Sign-In / OAuth), przetwarzamy wyłącznie następujące dane użytkownika Google:",
    "imp.googleNote" to "Korzystanie z informacji z Google API jest zgodne z <a href=\"https://developers.google.com/terms/api-services-user-data-policy\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-brand-400 hover:underline\">Google API Services User Data Policy</a>, w tym z wymogami Limited Use.",
    "imp.googleTitle" to "Logowanie Google (dane użytkownika Google)",
    "imp.host1" to "<b><a href=\"https://smartkomm.de/\" target=\"_blank\" rel=\"noopener noreferrer\">SmartKomm GmbH</a></b> udostępnia serwer (maszynę wirtualną) <b>bezpłatnie</b>; jej prezes prowadzi ten projekt prywatnie. Jedynym odpowiedzialnym za pumpfoil.org i wszystkie dane jest operator wskazany w nocie prawnej.",
    "imp.host2" to "Serwer znajduje się w <b><a href=\"https://www.hetzner.com\" target=\"_blank\" rel=\"noopener noreferrer\">Hetzner Online GmbH</a></b>. Z firmą Hetzner zawarta jest <b>umowa powierzenia przetwarzania danych zgodnie z art. 28 RODO</b>.",
    "imp.hostTitle" to "Serwer i hosting",
    "imp.huawei1" to "<b>Przesyłanie:</b> aplikacja na zegarku wysyła nagranie (trasa GPS, czas, dane ruchu, tętno) przez HUAWEI Health do aplikacji Pumpfoil na Twoim telefonie z Androidem (HUAWEI Wear Engine), która przesyła je na pumpfoil.org. HUAWEI WATCH 3, 4 i 5 mogą też przesyłać bezpośrednio po połączeniu kodem.",
    "imp.huawei2" to "<b>Dostęp na telefonie:</b> tylko podstawowe informacje o sparowanych zegarkach HUAWEI (nazwa, stan połączenia, czy aplikacja Pumpfoil jest zainstalowana na zegarku). Nie odczytujemy żadnych danych z Twojego HUAWEI ID, z HUAWEI Health ani z innych aplikacji.",
    "imp.huawei3" to "Nagrania są zapisywane wyłącznie jako Twoje własne sesje i traktowane jak pozostałe. Bez przekazywania osobom trzecim, bez reklam.",
    "imp.huawei4" to "Dostęp możesz cofnąć w każdej chwili: w aplikacji Pumpfoil na karcie zegarka HUAWEI („Rozłącz”) lub w HUAWEI Health. Za przetwarzanie po stronie Huawei odpowiada Huawei zgodnie z własną polityką prywatności.",
    "imp.huaweiIntro" to "Jeśli nagrywasz aplikacją Pumpfoil na zegarku HUAWEI, nagranie trafia do nas przez Twój telefon:",
    "imp.huaweiTitle" to "Zegarki HUAWEI (HUAWEI Health / Wear Engine)",
    "imp.intro" to "Ta aplikacja to społeczność: sesje foilowe są udostępniane innym. Poniżej dokładnie, które dane są dla kogo widoczne.",
    "imp.map1" to "<b>Mapa drogowa</b> pochodzi z <b>OpenStreetMap</b>. Przy wyświetlaniu mapy twoja przeglądarka pobiera kafelki bezpośrednio z ich serwerów; przekazywane są przy tym twój adres IP i wyświetlany fragment. Dostawca: OpenStreetMap Foundation, Wielka Brytania.",
    "imp.map2" to "Jeśli przyciskiem na mapie przełączysz się na <b>satelitę</b>, zdjęcia lotnicze pochodzą od <b>Esri</b> (Esri, Maxar, Earthstar Geographics) — również bezpośrednio z ich serwerów i również z twoim adresem IP. Dzieje się tak <b>tylko</b> wtedy, gdy przełączysz; twój wybór jest zapamiętywany lokalnie na twoim urządzeniu.",
    "imp.mapApple" to "W <b>aplikacji na iPhone'a i Apple Watch</b> zarówno mapa, JAK I zdjęcia lotnicze pochodzą z <b>Apple Maps</b>, a nie z OpenStreetMap ani Esri. Wyświetlenie mapy wysyła widoczny fragment do Apple; odpowiada za to Apple zgodnie ze swoją polityką prywatności. <b>Aplikacja na Androida</b> działa jak przeglądarka: mapa drogowa z OpenStreetMap, zdjęcia lotnicze z Esri.",
    "imp.mapSpots" to "<b>Nazwy spotów</b>: nasz serwer wyszukuje nazwy miejscowości i akwenów dla współrzędnych spotu w usługach OpenStreetMap (Nominatim i Overpass, w tym lustro Overpass prowadzone przez VK/mail.ru). Przesyłane są tylko współrzędne spotu, żadne dane konta. Dla spotów na morzu bierzemy najbliższą miejscowość z <b>GeoNames</b> (geonames.org, CC BY 4.0) — listy przechowywanej na naszym serwerze.",
    "imp.mapTitle" to "Mapy",
    "imp.mcp1" to "Opcjonalnie możesz dać programowi AI (np. Claude od Anthropic) dostęp do odczytu twoich własnych nagrań, tylko jeśli wyraźnie na to pozwolisz na naszej stronie zgody (OAuth).",
    "imp.mcp2" to "Program może tylko czytać i tylko twoje własne nagrania, sumy i najlepsze wyniki wraz ze sprzętem. Żadnych danych innych riderów, zdjęć, filmów, wiadomości ani ocen, żadnych odrzuconych ani usuniętych nagrań.",
    "imp.mcp3" to "To, co program pobierze, przetwarza jego dostawca na własnych warunkach. Dostęp możesz zakończyć w każdej chwili w „Połączone konta”.",
    "imp.mcpTitle" to "Programy AI z twoimi nagraniami (dostęp AI)",
    "imp.operator1" to "Adresy e-mail, wszystkie surowe dane, powiązania urządzeń i techniczne logi serwera.",
    "imp.operator2" to "Hasła są przechowywane wyłącznie jako solony skrót (PBKDF2) — nawet ja nie widzę ich w postaci jawnej.",
    "imp.operator3" to "Technicznie operator ma wgląd we wszystkie zapisane treści, także w wiadomości prywatne i czaty drużyn (zob. też „Wsparcie AI”).",
    "imp.operatorTitle" to "🛠 Tylko operator (Jan)",
    "imp.owner1" to "<b>Surowe dane</b> Twoich sesji (pojedyncze punkty GPS, przyspieszenie 25 Hz) — np. do etykietowania.",
    "imp.owner2" to "Etykiety, przycinanie, ponowna analiza, wysyłanie/usuwanie zdjęć.",
    "imp.owner3" to "Twój <b>adres e-mail</b> i ustawienia konta — nigdy widoczne dla innych użytkowników.",
    "imp.owner4" to "Tylko ty widzisz, kto polubił twoją sesję; inni widzą tylko liczbę. Kto zgłosił „wygląda na fałszywe” lub „nieodpowiednie”, nie jest nikomu pokazywane.",
    "imp.owner5" to "<b>Trwające nagrania</b>: jeśli rejestrator w telefonie wysyła na żywo (przełącznik „Wysyłaj na żywo” w profilu, można wyłączyć), dane GPS i ruchu trafiają na nasz serwer już podczas nagrywania. To, że i od kiedy trwa nagrywanie, widzisz na swoich innych urządzeniach i zegarkach. Z twoim imieniem widzą to poza tobą tylko twoi potwierdzeni znajomi, razem ze spotem (zob. „Twoi znajomi”); bez imienia twój spot może zazielenić się na mapie spotów (następny punkt). W przypadku zegarków „prawdopodobnie nagrywa” wynika wyłącznie z tego, kiedy aplikacja zegarka ostatnio się odezwała. Sama sesja pojawia się dla innych dopiero po zakończeniu.",
    "imp.owner6" to "<b>Aktywne spoty</b>: mapa spotów koloruje na zielono spoty, gdzie prawdopodobnie ktoś teraz pompuje. Bierzemy spot w promieniu 1 km od twojego trwającego nagrania telefonem lub od pozycji, którą zegarek zgłasza raz przy uruchomieniu (zapisujemy tylko spot, nie pozycję), a po przesłaniu spot twojej sesji. Jeśli w pobliżu nie ma spotu, sesja nie ma rozpoznanych przejazdów albo ją usuniesz, nie liczysz się jako aktywny. Pojedynczy spot robi się zielony tylko przy co najmniej 4 riderach w ciągu ostatnich 180 dni; mniejsze spoty kolorują tylko grupę, i to tylko gdy spoty w okolicy miały ponad 5 riderów w ciągu ostatnich 90 dni. Imiona nie są pokazywane. Możesz to wyłączyć w profilu („Pokazuj mnie na mapie spotów”).",
    "imp.ownerTitle" to "🔒 Tylko Ty (właściciel sesji)",
    "imp.privacyText" to "Wszystkie wysłane dane są przechowywane trwale. Aby je usunąć, użyj przycisku „Usuń konto” w swoim profilu (aplikacja webowa albo iOS/Android) — trwale usuwa on Twoje konto ze wszystkimi sesjami, surowymi danymi i zdjęciami. Przesyłanie jest szyfrowane (HTTPS).",
    "imp.privacyTitle" to "Usuwanie danych",
    "imp.public1" to "<b>Wysłane zdjęcia</b> i <b>zdjęcia profilowe</b>: pliki obrazów leżą pod losowym, nieodgadywalnym linkiem. Każdy, kto zna ten link (np. przesłany dalej), może otworzyć obraz bez konta. Dane EXIF/GPS w zdjęciach są usuwane przy wysyłaniu.",
    "imp.public2" to "Sama aplikacja webowa i pobranie aplikacji na zegarek.",
    "imp.public3" to "<b>Publiczne rankingi drużyn</b>: jeśli kierownictwo drużyny upubliczni jej rankingi, każdy widzi je bez logowania, także przez udostępnione linki do eventów: miejsce, nazwę wyświetlaną, inicjały i wartość. Sesje, spoty i zdjęcia profilowe widzą tylko zalogowani. Wyszukiwarki nie indeksują stron drużyn.",
    "imp.public4" to "<b>Globalne eventy</b> pumpfoil.org: biorą w nich udział automatycznie wszyscy z pasującymi sesjami, bez zapisywania się. Ich rankingi są widoczne przez link do eventu także bez logowania (miejsce, nazwa wyświetlana, inicjały, wartość), a twoje wyniki liczą się do klasyfikacji twoich drużyn. Możesz to wyłączyć w profilu w „Prywatność” opcją „Nie bierz udziału w globalnych eventach”; wtedy znikasz też z eventów, które już się skończyły.",
    "imp.publicTitle" to "🌍 Publicznie (każdy w internecie, bez logowania)",
    "imp.teams1" to "<b>Ty decydujesz</b>, czy dołączasz do drużyny; okno dołączania mówi ci wcześniej, czy jej rankingi są obecnie publiczne. Odejść możesz w każdej chwili i wtedy od razu znikasz z rankingów drużyny. Tylko w eventach, które już się skończyły, zostajesz w zamrożonym wyniku.",
    "imp.teams2" to "<b>Kierownictwo drużyny decyduje</b>, czy rankingi są publiczne, kto widzi listę członków (tylko członkowie albo wszyscy zalogowani) oraz jakie są rankingi i eventy. Dołączając, zgadzasz się, że rankingi mogą być publiczne, nawet jeśli teraz nie są; wtedy twoja nazwa wyświetlana i miejsce są widoczne bez logowania. Nie da się ukryć pojedynczych członków.",
    "imp.teams3" to "Liczą się wszystkie twoje sesje, także sprzed dołączenia; w eventach tylko te z okresu eventu. Miejsca 1–3 w evencie dostają odznakę na swojej stronie profilu.",
    "imp.teams4" to "Przy prośbie o dołączenie kierownictwo i moderatorzy widzą, na których spotach i w jakich sportach dotąd się pojawiałeś (tylko liczbę sesji).",
    "imp.teams5" to "Drużyna pojawia się publicznie z nazwą, opisem, herbem i obrazem dopiero po naszej akceptacji. Jeśli twoje konto zostanie usunięte, znikasz ze wszystkich drużyn i rankingów, także z zamrożonych wyników eventów.",
    "imp.teamsTitle" to "🏁 Drużyny: co decydujesz ty, a co kierownictwo drużyny",
    "imp.title" to "Impressum",
    "imp.werteText" to "Obiecujemy dokładnie jedno: na serwerze działa publiczny kod źródłowy z GitHuba. Wyświetlane jest to, co oblicza z przesłanych danych, nawet jeśli liczby są błędne lub nieoczekiwane. Nie obiecujemy, że pomiary, sesje, rekordy, rankingi i eventy są poprawne lub niezmanipulowane.",
    "imp.werteTitle" to "Pomiary i to, co wyświetlamy",
    "imp.whoSees" to "Prywatność",
    "imp.yt1" to "Na stronie głównej pokazujemy miniatury z naszego kanału YouTube. Są serwowane przez <b>nasz własny serwer</b> — samo wczytanie strony <b>nie</b> nawiązuje kontaktu z Google i <b>nie</b> ustawia żadnych ciasteczek.",
    "imp.yt2" to "Dopiero gdy <b>klikniesz</b> wideo, ładowany jest odtwarzacz YouTube (tryb rozszerzonej prywatności, youtube-nocookie.com). Google/YouTube otrzymuje wtedy Twój adres IP i może ustawić ciasteczka. Klikając, wyrażasz na to zgodę.",
    "imp.ytNote" to "Dostawca: Google Ireland Ltd. Więcej w <a href=\"https://policies.google.com/privacy\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-brand-400 hover:underline\">polityce prywatności Google</a>.",
    "imp.ytTitle" to "Osadzone wideo z YouTube",
    "ref.ablehnen" to "Odrzuć",
    "ref.alsEntwurf" to "Zapisz jako szkic",
    "ref.anlegen" to "Przygotuj korektę",
    "ref.aufheben" to "Wycofaj",
    "ref.aufhebenFrage" to "Wycofać korektę? {lauf} ridera {fahrer} znów się liczy, a rider dostanie powiadomienie.",
    "ref.bearbeiten" to "Edytuj",
    "ref.bearbeitetAm" to "edytowano {am}",
    "ref.bestaetigen" to "To usunie {lauf} ridera {fahrer} z rankingu, pokaże powód i komentarz publiczny na stronie wydarzenia i powiadomi ridera.",
    "ref.bestaetigtVon" to "opublikował(a) {von}",
    "ref.diskussion" to "Dyskusja (tylko referees)",
    "ref.einleitung" to "Usuwanie przejazdów z rankingu w kontrolowanych krokach: korekta zaczyna jako szkic, trafia do weryfikacji i działa dopiero po opublikowaniu. Opublikowane korekty widać na stronie wydarzenia, a rider dostaje powiadomienie.",
    "ref.entwurfHinweis" to "Zapisana jako szkic: bez skutku i widoczna tylko dla referees.",
    "ref.erstellt" to "Utworzył(a) {von} · {am}",
    "ref.fehler.eigener_lauf" to "Nie możesz zgłosić własnego przejazdu.",
    "ref.fehler.frist_abgelaufen" to "Wynik końcowy jest ustalony, to już nie działa.",
    "ref.fehler.grund" to "Wybierz powód.",
    "ref.fehler.kein_lauf" to "Nie znaleziono tego przejazdu w sesji.",
    "ref.fehler.kein_referee" to "Tylko referees mogą to zrobić.",
    "ref.fehler.melden_vorbei" to "Zgłoszenia zamykają się po ustaleniu wyniku.",
    "ref.fehler.nicht_in_wertung" to "Zgłaszać mogą tylko riderzy w rankingu.",
    "ref.fehler.nicht_mehr_aenderbar" to "Opublikowanych lub zamkniętych korekt nie można już zmieniać.",
    "ref.fehler.schon_gemeldet" to "Ten przejazd został już zgłoszony.",
    "ref.fehler.schon_vorhanden" to "Dla tego przejazdu jest już korekta.",
    "ref.fehler.uebergang" to "Ten krok nie jest możliwy z obecnego statusu.",
    "ref.fehler.zu_viele" to "Za dużo zgłoszeń dla tego wydarzenia.",
    "ref.feldGrund" to "Powód",
    "ref.feldIntern" to "Notatka wewnętrzna (tylko referees)",
    "ref.feldOeffentlich" to "Komentarz publiczny (na stronie wydarzenia)",
    "ref.frist" to "Korekty mogą działać do {zeit}.",
    "ref.fristAbgelaufen" to "Wynik końcowy jest ustalony; korekty już nie działają.",
    "ref.fristOffen" to "Wydarzenie jest jeszcze otwarte; korekty działają od razu po opublikowaniu.",
    "ref.grund.andere_sportart" to "Inny sport",
